// Compile: g++ -std=c++17 -o output program.cpp -I/path/to/morph/include

#include "morph.hpp"
#include <iostream>
#include <cmath>
#include <algorithm>

int main() {
    // Imagem de referência (produto sem defeito)
    mm::Image product_color = mm::read("https://scikit-image.org/_static/img/logo.png"); // Nota: data.coffee() não está disponível diretamente, usando uma imagem de exemplo
    // Para uma imagem de café, seria necessário carregar de um arquivo local
    // Por simplicidade, vamos criar uma imagem gradiente como exemplo
    mm::Image product_gray(300, 400); // Simulando uma imagem em tons de cinza

    // Preenchendo com um gradiente simulado (para demonstração)
    for (int y = 0; y < 300; y++) {
        for (int x = 0; x < 400; x++) {
            product_gray.at(y, x) = static_cast<unsigned char>((x * 200) / 400 + (y * 55) / 300);
        }
    }

    // Inserção de defeito simulado: arranhão escuro de 10×100 px
    mm::Image defect_image = product_gray;
    for (int y = 100; y < 110; y++) {
        for (int x = 200; x < 300; x++) {
            defect_image.at(y, x) = static_cast<unsigned char>(0.1 * 255);
        }
    }

    // Detecção por subtração e limiarização
    mm::Image difference(300, 400);
    for (int y = 0; y < 300; y++) {
        for (int x = 0; x < 400; x++) {
            difference.at(y, x) = static_cast<unsigned char>(std::abs((int)product_gray.at(y, x) - (int)defect_image.at(y, x)));
        }
    }

    int defect_threshold = static_cast<int>(0.15 * 255); // ajustável conforme a aplicação
    mm::Image detected_defect(300, 400);
    for (int y = 0; y < 300; y++) {
        for (int x = 0; x < 400; x++) {
            detected_defect.at(y, x) = (difference.at(y, x) > defect_threshold) ? 255 : 0;
        }
    }

    mm::show({product_gray, defect_image, detected_defect}, MM_OUT, {"Referência", "Com defeito", "Defeito detectado"}, 3);

    bool has_defect = false;
    for (int y = 0; y < 300 && !has_defect; y++) {
        for (int x = 0; x < 400; x++) {
            if (detected_defect.at(y, x) > 0) {
                has_defect = true;
                break;
            }
        }
    }

    if (has_defect) {
        std::cout << "Defeito detectado." << std::endl;
    } else {
        std::cout << "Produto conforme." << std::endl;
    }

    return 0;
}

