// Compile: g++ -std=c++17 -O2 program.cpp -o program && ./program
#include "morph.hpp"
#include <iostream>
#include <vector>
#include <string>
#include <random>
#include <algorithm>

// | label: fig-03-ruido
// | fig-cap: "Salt and pepper noise with increasing densities (2%, 5%, 10%). The prob parameter indicates the total fraction of corrupted pixels, half salt (255) and half pepper (0)."
// | echo: true
// | output: true

std::pair<mm::Image, int> add_salt_pepper(const mm::Image& img, double prob=0.05, int seed=42) {
    /* Adds salt and pepper noise with total probability prob. */
    mm::Image noisy = img;  // copy
    std::mt19937 rng(seed);
    std::uniform_real_distribution<double> dist(0.0, 1.0);

    int n_corrompidos = 0;
    for (int y = 0; y < img.h; ++y) {
        for (int x = 0; x < img.w; ++x) {
            double rnd = dist(rng);
            if (rnd < prob / 2) {
                noisy.at(y, x) = 0;      // pepper
                ++n_corrompidos;
            } else if (rnd > 1 - prob / 2) {
                noisy.at(y, x) = 255;    // salt
                ++n_corrompidos;
            }
        }
    }
    return {noisy, n_corrompidos};
}

int main() {
    // Assume img_gray_crop is available (grayscale image)
    mm::Image img_gray_crop;  // This should be loaded/created beforehand

    std::vector<double> probs = {0.02, 0.05, 0.10};
    std::vector<mm::Image> imgs_noise = {img_gray_crop};
    std::vector<std::string> titles_noise = {"Original"};

    for (double p : probs) {
        auto [noisy, n] = add_salt_pepper(img_gray_crop, p);
        imgs_noise.push_back(noisy);
        titles_noise.push_back("Ruído " + std::to_string((int)(p * 100)) + "%\n(" + 
                              std::to_string(n) + " pixels)");
    }

    mm::show(imgs_noise, MM_OUT, titles_noise, 4);
    return 0;
}

