#include "morph.hpp"
#include <iostream>
#include <string>
#include <vector>
#include <cmath>
#include <filesystem>

int main() {
    // https://commons.wikimedia.org/wiki/File:Mandrill-k-means.png
    std::string url    = "https://upload.wikimedia.org/wikipedia/commons/a/ab/Mandrill-k-means.png";
    std::string caminho = "imagens/mandrill.png";
    namespace fs = std::filesystem;

    // ── Leitura RGB ───────────────────────────────────────────────────────────
    mm::Image img_rgb;
    if (!fs::exists(caminho)) {
        fs::create_directories("imagens");
        mm::Image img_pil = mm::read(url);
        mm::write(img_pil, caminho);
        img_rgb = img_pil;
    } else {
        img_rgb = mm::read(caminho);
    }

    // ── Criação do canal alfa (gradiente horizontal) ──────────────────────────
    int h = img_rgb.h;
    int w = img_rgb.w;
    mm::Image img_rgba(h, w, 4);

    // Copy RGB channels
    for (int y = 0; y < h; y++) {
        for (int x = 0; x < w; x++) {
            for (int c = 0; c < 3; c++) {
                img_rgba.at(y, x, c) = img_rgb.at(y, x, c);
            }
            // Alpha channel: horizontal gradient
            img_rgba.at(y, x, 3) = static_cast<unsigned char>(255.0 * x / (w - 1));
        }
    }

    // ── Diagnóstico ───────────────────────────────────────────────────────────
    unsigned char rgb_min = 255, rgb_max = 0;
    unsigned char rgba_min = 255, rgba_max = 0;
    for (int y = 0; y < h; y++) {
        for (int x = 0; x < w; x++) {
            for (int c = 0; c < 3; c++) {
                rgb_min = std::min(rgb_min, img_rgb.at(y, x, c));
                rgb_max = std::max(rgb_max, img_rgb.at(y, x, c));
                rgba_min = std::min(rgba_min, img_rgba.at(y, x, c));
                rgba_max = std::max(rgba_max, img_rgba.at(y, x, c));
            }
            rgba_min = std::min(rgba_min, img_rgba.at(y, x, 3));
            rgba_max = std::max(rgba_max, img_rgba.at(y, x, 3));
        }
    }

    std::cout << "RGB   → shape=(" << h << ", " << w << ", 3), dtype=uint8, "
              << "faixa=[" << static_cast<int>(rgb_min) << ", " << static_cast<int>(rgb_max) << "]\n";
    std::cout << "RGBA  → shape=(" << h << ", " << w << ", 4), dtype=uint8, "
              << "faixa=[" << static_cast<int>(rgba_min) << ", " << static_cast<int>(rgba_max) << "]\n";
    std::cout << "Pixel (0,0): RGB=(" 
              << static_cast<int>(img_rgb.at(0,0,0)) << ", "
              << static_cast<int>(img_rgb.at(0,0,1)) << ", "
              << static_cast<int>(img_rgb.at(0,0,2)) << ")  |  RGBA=("
              << static_cast<int>(img_rgba.at(0,0,0)) << ", "
              << static_cast<int>(img_rgba.at(0,0,1)) << ", "
              << static_cast<int>(img_rgba.at(0,0,2)) << ", "
              << static_cast<int>(img_rgba.at(0,0,3)) << ")\n";

    // ── Normalização float32 (padrão scikit-image / PyTorch) ──────────────────
    float norm_min = 1.0f, norm_max = 0.0f;
    std::vector<std::vector<std::vector<float>>> img_rgb_norm(h, 
        std::vector<std::vector<float>>(w, std::vector<float>(3)));
    for (int y = 0; y < h; y++) {
        for (int x = 0; x < w; x++) {
            for (int c = 0; c < 3; c++) {
                img_rgb_norm[y][x][c] = static_cast<float>(img_rgb.at(y,x,c)) / 255.0f;
                norm_min = std::min(norm_min, img_rgb_norm[y][x][c]);
                norm_max = std::max(norm_max, img_rgb_norm[y][x][c]);
            }
        }
    }
    std::cout << "\nNormalizado (float32): faixa=[" << norm_min << ", " << norm_max << "]\n";
    std::cout << "Pixel (0,0) normalizado: [" 
              << img_rgb_norm[0][0][0] << ", "
              << img_rgb_norm[0][0][1] << ", "
              << img_rgb_norm[0][0][2] << "]\n";

    // ── Visualização ──────────────────────────────────────────────────────────
    mm::show(std::vector<mm::Image>{img_rgb, img_rgba}, MM_OUT,
             std::vector<std::string>{"RGB  —  M × N × 3", "RGBA  —  M × N × 4"}, 2);

    return 0;
}

