def _viz(f, B, y, x):
    """Generates (vy, vx, b_val) for each valid neighbor of (y,x)."""
    H, W = f.shape
    Bh, Bw = B.shape
    oh, ow = -Bh/2 + 0.5, -Bw/2 + 0.5  # fixed offsets
    for by, bx in np.ndindex(Bh, Bw):
        vy, vx = int(y + by + oh), int(x + bx + ow)
        if 0 <= vy < H and 0 <= vx < W:
            yield vy, vx, B[by, bx]

def ero(f, Bc=np.zeros((3,3),dtype='uint8')):
    """Erosion (OpenCV or with weights)."""
    try:    return cv2.erode(f, Bc)
    except: return mm.ero1(f, Bc)

def ero0(f, Bc=np.ones((3,3),dtype='uint8')):
    """Classical erosion without weights."""
    g = np.empty_like(f)
    for y in range(f.shape[0]):
        for x in range(f.shape[1]):
            g[y,x] = 255
            for vy,vx,bv in mm._viz(f,Bc,y,x):
                if bv and g[y,x] > f[vy,vx]: g[y,x] = f[vy,vx]
    return g

# Test and Validation Script
B = mm.secross()
print("Structuring element B:")
print(mm.drawImage(B))

f = mm.randomImage(5,5)
print("Original image f:")
print(mm.drawImage(f))

print("Didactic Flat Erosion (ero0):")
print(mm.drawImage(ero0(f, B)))

print("Optimized OpenCV Erosion (ero):")
print(mm.drawImage(ero(f, B)))

