int main() {
    // Constantes
    const std::vector<std::string> RACAS_ALVO = {"Pug", "Boxer"};
    const int N_TREINO_POR_CLASSE = 15;
    const int N_TESTE_POR_CLASSE = 20;

    // 1. Téléchargement du dataset complet (37 races) — licence CC BY-SA 4.0
    // Note : Le téléchargement du dataset n'est pas disponible dans cette traduction C++.
    // Nous simulons les données avec des images aléatoires.
    std::cout << "Téléchargement du dataset simulé (Oxford-IIIT Pet)\n";

    // Simulation des données : nous créons des images aléatoires pour simuler le dataset
    // (remplace par le vrai chargement de données si disponible)
    std::vector<std::vector<mm::Image>> por_classe(2);
    std::mt19937 rng_gen(42);

    // Simuler 100 images par classe (fichiers d'images aléatoires)
    for (int classe = 0; classe < 2; ++classe) {
        for (int i = 0; i < 100; ++i) {
            mm::Image img = mm::randomImage(128, 128, 255);
            por_classe[classe].push_back(img);
        }
    }

    // 2. Filtrage des deux races d'intérêt, séparées par classe
    // (Déjà fait ci-dessus dans la simulation)

    // 3. Échantillonnage : peu d'images d'entraînement, plus d'images de test
    std::mt19937 rng(42);
    std::vector<mm::Image> imgs_treino;
    std::vector<int> y_treino;
    std::vector<mm::Image> imgs_teste;
    std::vector<int> y_teste;

    for (int classe_idx = 0; classe_idx < 2; ++classe_idx) {
        std::vector<mm::Image> imgs_raca = por_classe[classe_idx];
        std::shuffle(imgs_raca.begin(), imgs_raca.end(), rng);

        // Images d'entraînement
        for (int i = 0; i < N_TREINO_POR_CLASSE; ++i) {
            imgs_treino.push_back(imgs_raca[i]);
            y_treino.push_back(classe_idx);
        }

        // Images de test
        for (int i = N_TREINO_POR_CLASSE; i < N_TREINO_POR_CLASSE + N_TESTE_POR_CLASSE; ++i) {
            imgs_teste.push_back(imgs_raca[i]);
            y_teste.push_back(classe_idx);
        }
    }

    std::cout << "Treino: " << imgs_treino.size() << " images | Teste: " << imgs_teste.size() << " images\n";

    // Sélection des échantillons pour l'affichage
    std::vector<mm::Image> amostras_pil;
    for (int i = 0; i < 4; ++i) {
        amostras_pil.push_back(imgs_treino[i]);
    }
    for (int i = N_TREINO_POR_CLASSE; i < N_TREINO_POR_CLASSE + 4; ++i) {
        amostras_pil.push_back(imgs_treino[i]);
    }

    std::vector<mm::Image> amostras_exibicao = amostras_pil;  // Conversion directe (déjà RGB)
    std::vector<std::string> titulos_exibicao;
    for (int i = 0; i < 4; ++i) {
        titulos_exibicao.push_back(RACAS_ALVO[0]);
    }
    for (int i = 0; i < 4; ++i) {
        titulos_exibicao.push_back(RACAS_ALVO[1]);
    }

    mm::show(amostras_exibicao, MM_OUT, titulos_exibicao, 4);

    return 0;
}

