// Compile with: g++ -std=c++17 -O2 program.cpp -o program
#include <iostream>
#include <vector>
#include <algorithm>
#include <numeric>
#include <cmath>

int main() {
    // Exemplo numérico: média vs. mediana com pixel corrompido
    std::vector<int> vizinhanca = {102, 98, 105, 100, 255, 97, 103, 99, 101};

    // Sort a copy for display
    std::vector<int> sorted_viz = vizinhanca;
    std::sort(sorted_viz.begin(), sorted_viz.end());

    std::cout << "Vizinhança: [";
    for (size_t i = 0; i < sorted_viz.size(); ++i) {
        std::cout << sorted_viz[i];
        if (i < sorted_viz.size() - 1) std::cout << ", ";
    }
    std::cout << "]\n";

    // Calculate mean
    double media = 0.0;
    for (int x : vizinhanca) {
        media += x;
    }
    media /= vizinhanca.size();

    std::cout << "Média:      " << media << "  (deslocada pelo outlier 255)\n";

    // Calculate median
    std::vector<int> sorted_for_median = vizinhanca;
    std::sort(sorted_for_median.begin(), sorted_for_median.end());
    int mediana = sorted_for_median[sorted_for_median.size() / 2];

    std::cout << "Mediana:    " << mediana << "    (ignora o outlier)\n";
    std::cout << "Valor original:  ~100\n";

    return 0;
}

