      </div>
      <input type="range" id="sim_ep0203_sl_bits" min="1" max="8" step="1" value="8" style="width:100%;cursor:pointer;">
      <div style="margin-top:6px;font-size:10px;color:#8a8371;text-align:center;font-family:monospace;">
