// Compile with: g++ -std=c++17 -I. -o quantize quantize.cpp -lm

#include "morph.hpp"
#include <iostream>
#include <vector>
#include <string>
#include <cmath>

// Helper function to compute 2^bits
int pow2(int bits) {
    return 1 << bits;
}

// Function to quantize image and return image + label
std::pair<mm::Image, std::string> quantize_simple(const mm::Image& image, int bits) {
    int levels = pow2(bits);

    // Create quantized image
    mm::Image quantized(image.h, image.w);

    // Uniform quantization: floor(image/256 * levels) / levels * 255
    for (int y = 0; y < image.h; y++) {
        for (int x = 0; x < image.w; x++) {
            float normalized = static_cast<float>(image.at(y, x)) / 256.0f;
            float quantized_val = std::floor(normalized * levels) / levels * 255.0f;
            quantized.at(y, x) = static_cast<unsigned char>(quantized_val);
        }
    }

    // Calculate memory in KB
    double mem_kb = static_cast<double>(quantized.h * quantized.w) / 1024.0;

    // Build label string
    std::string label = std::to_string(bits) + " bits (" + std::to_string(levels) + " níveis)\n" 
                       + std::to_string(static_cast<int>(mem_kb)) + " KB";

    return {quantized, label};
}

int main() {
    // Load the grayscale image
    std::string img_url = "https://raw.githubusercontent.com/agostinhobritojr/imagens/master/Fig0304a.tif";
    mm::Image img_gray = mm::read(img_url, true);

    // List of bits to test (8 is default, 1 is binary)
    std::vector<int> bits_test = {8, 4, 2, 1};

    // Generate results and separate into lists for mm::show
    std::vector<mm::Image> imgs_q;
    std::vector<std::string> titles_q;

    for (int b : bits_test) {
        auto result = quantize_simple(img_gray, b);
        imgs_q.push_back(result.first);
        titles_q.push_back(result.second);
    }

    // Show the results
    mm::show(imgs_q, MM_OUT, titles_q, 4);

    return 0;
}

