  #sim-08-ransac canvas { display: block; max-width: 100%; height: auto; border-radius: 8px; border: 1px solid #e4dcc8; background: #ffffff; margin: 0 auto; }
  #sim-08-ransac button { font-size: 11px; padding: 6px 12px; border-radius: 8px; border: 1px solid #e4dcc8; background: #f1ead7; color: #5e5a4a; cursor: pointer; transition: all 0.15s ease; font-weight: 600; display: inline-flex; align-items: center; justify-content: center; gap: 5px; }
  #sim-08-ransac button:hover { background: #e8dfcf; }
  #sim-08-ransac button.sim-08-ransac_primary { background: #26241d !important; border-color: #26241d !important; color: #7ee7c6 !important; }
