  <span style="font-weight:600;color:#26241d;">🎯 Simulator: RANSAC — Robust Line Fitting to Outliers</span>
  <span class="sim-08-ransac_pill">Data with ~25% spurious correspondences</span>
</div>

<div style="padding:16px;background:#ffffff;">

  <!-- Painel de Estatísticas e Controles -->
  <div class="sim-08-ransac_panel" style="margin-bottom:14px;">

    <div class="sim-08-ransac_grid_stats">
      <div class="sim-08-ransac_stat_box">
        <div class="sim-08-ransac_stat_label">Threshold (px)</div>
        <div id="sim-08-ransac_thVal" class="sim-08-ransac_stat_value" style="color:#b9770e;">15</div>
      </div>
      <div class="sim-08-ransac_stat_box">
        <div class="sim-08-ransac_stat_label">Inliers</div>
        <div id="sim-08-ransac_nIn" class="sim-08-ransac_stat_value" style="color:#27ae60;">–</div>
      </div>
      <div class="sim-08-ransac_stat_box">
        <div class="sim-08-ransac_stat_label">Outliers</div>
        <div id="sim-08-ransac_nOut" class="sim-08-ransac_stat_value" style="color:#c0392b;">–</div>
      </div>
      <div class="sim-08-ransac_stat_box">
        <div class="sim-08-ransac_stat_label">Iterations</div>
        <div id="sim-08-ransac_nIter" class="sim-08-ransac_stat_value" style="color:#2980b9;">–</div>
      </div>
