      pixels = Array.from({ length: N }, function(){ return Math.floor(Math.random() * 256); });
    }

    function resetMask() {
      mask = Array.from({ length: N }, function(_, i) {
        var r = Math.floor(i / 4), c = i % 4;
        return (r + c) % 2 === 0 ? 255 : 0;
      });
    }

    function render() {
      gridF.innerHTML = '';
      gridMask.innerHTML = '';
      gridResult.innerHTML = '';

      var preserved = 0, zeroed = 0;

      for (var i = 0; i < N; i++) {
