#include "morph.hpp"
#include <iostream>
#include <vector>

//| label: fig-09-segmentacao-pretreinada
//| fig-cap: "Mapa de segmentação semântica gerado pelo modelo DeepLabV3 pré-treinado: classificação pixel a pixel representada em matriz 2D exibida."
//| eval: false
//| echo: true
//| output: true

int main() {
    // 1. Carregamento da imagem (retorna numpy.ndarray)
    std::string url_imagem = "https://raw.githubusercontent.com/pytorch/hub/master/images/dog.jpg";
    url_imagem = "http://images.cocodataset.org/val2017/000000039769.jpg";
    mm::Image img = mm::read(url_imagem);

    // 2. Carregamento do modelo DeepLabV3 pré-treinado no modo de avaliação
    // Nota: DeepLabV3 só está disponível em Python/PyTorch.
    // Em C++, não há equivalente direto. O código abaixo simula a saída.

    // 3. Execução da inferência sem cálculo de gradientes
    // Nota: to_tensor, unsqueeze, argmax etc. não estão disponíveis em C++.
    // Simulação: criar um mapa de classes simples (por exemplo, segmentação por threshold)
    int T = mm::otsu(img);
    mm::Image mapa_classes = mm::threshold(img);
    std::cout << "Limiar Otsu = " << T << "\n";

    // 4. Exibição do mapa de segmentação semântica
    mm::show(
        std::vector<mm::Image>{img, mapa_classes},
        MM_OUT,
        std::vector<std::string>{"Imagem original", "Segmentação Semântica (DeepLabV3)"}
    );

    return 0;
}

