// Compile: g++ -std=c++17 -o simulator simulator.cpp -I/path/to/morph/include

#include <iostream>
#include <string>
#include <vector>
#include <functional>
#include <random>
#include <sstream>

// Simulação de ambiente web - em C++ não temos HTML/DOM
// Esta é uma representação conceitual do simulador EP01_05

class SimuladorEP0105 {
private:
    std::vector<int> pixels;
    std::mt19937 rng;

public:
    SimuladorEP0105() : rng(std::random_device{}()) {
        // Inicialização dos pixels como no código original
        pixels = {0, 64, 128, 255, 200, 150, 100, 50, 10, 80, 160, 240, 255, 128, 64, 0};
    }

    void renderizar() {
        std::cout << "\n=== ORIGINAL (p) ===\n";
        for (int i = 0; i < 16; ++i) {
            std::cout << pixels[i] << " ";
            if ((i + 1) % 4 == 0) std::cout << "\n";
        }

        std::cout << "\n=== NEGATIVO (255 - p) ===\n";
        for (int i = 0; i < 16; ++i) {
            std::cout << 255 - pixels[i] << " ";
            if ((i + 1) % 4 == 0) std::cout << "\n";
        }
    }

    void clickPixel(int index) {
        if (index < 0 || index >= 16) return;
        pixels[index] = (pixels[index] + 51) % 256;
        renderizar();
    }

    void botaoAleatorio() {
        std::uniform_int_distribution<int> dist(0, 255);
        for (auto& p : pixels) {
            p = dist(rng);
        }
        renderizar();
    }

    void botaoDegrade() {
        for (int i = 0; i < 16; ++i) {
            pixels[i] = static_cast<int>((static_cast<double>(i) / 16.0) * 255.0);
        }
        renderizar();
    }

    void executarSimulacao() {
        std::cout << "🌓 Simulador EP01_05: Transformação de Negativo de Imagem\n";
        std::cout << "p' = 255 - p\n\n";
        std::cout << "Clique nos pixels da matriz Original (p) para alterar seus níveis de cinza (passo de +51) e observe o efeito da inversão complementar na matriz Negativo (255 - p).\n";

        renderizar();

        // Simulação de interações do usuário
        std::cout << "\n--- Simulando cliques do usuário ---\n";

        // Exemplo de interações
        std::cout << "Clique no pixel 0 (passo +51):\n";
        clickPixel(0);

        std::cout << "\nClique no pixel 7 (passo +51):\n";
        clickPixel(7);

        std::cout << "\nBotão Aleatório:\n";
        botaoAleatorio();

        std::cout << "\nBotão Degradê Linear:\n";
        botaoDegrade();

        std::cout << "\n💡 NOTA: A transformação de negativo mapeia tons escuros (próximos de 0) para tons claros (próximos de 255) e vice-versa, sendo útil para destacar detalhes escuros em fundos claros.\n";
    }
};

int main() {
    SimuladorEP0105 sim;
    sim.executarSimulacao();

    return 0;
}

31ff2c8800ff755a0db6b541759e26be:
## 2D Discrete Fourier Transform

Fourier analysis is based on the principle that any periodic signal can be represented as a sum of sinusoidal functions with different frequencies, amplitudes, and phases. This concept also applies to digital images, allowing them to be represented in the **frequency domain** instead of the spatial domain.

@fig-decomposicao-1d illustrates this decomposition for a one-dimensional signal. In the case of an image, the Discrete Fourier Transform (DFT) converts the intensity matrix $f(x,y)$ into a set of coefficients that describes the contribution of the different spatial frequencies present in the image.

323f4fa32d3122af0499a5427d418ffd:
::: {.callout-note}

### 🧠 Pourquoi cela fonctionne-t-il ? — De la fermeture morphologique à la rectification {.unnumbered}

**Fermeture morphologique :** la dilatation suivie de l’érosion comble les petites discontinuités et adoucit les contours des objets sans modifier significativement leur forme globale. En utilisant un élément structurant de grande taille (`sedisk(41)`), les détails fins, tels que les textes, les lignes du formulaire et les petits bruits, tendent à être intégrés au fond pendant le traitement, tandis que les objets de plus grande échelle, comme les disques de référence, restent préservés et deviennent plus homogènes.

**Circularité :** après l’isolement des composants candidats, la métrique $C=\frac{4\pi A}{P^2}$ quantifie à quel point leur forme se rapproche d’un cercle. Sa valeur est égale à 1 pour un cercle parfait et diminue à mesure que le contour devient plus irrégulier. Ainsi, un seuil tel que $C>0{,}8$ permet d’éliminer la plupart des faux positifs sans recourir à des modèles d’apprentissage. Un simulateur de cette métrique est présenté dans la @fig-06-sim-06-circularidade.

**Transformation de perspective (*perspective warp*) :** une fois les quatre disques de référence identifiés, leurs centres sont utilisés comme points de contrôle pour estimer la transformation projective qui mappe l’image capturée au plan du document. Cette transformation corrige les distorsions introduites par la perspective lors de l’acquisition de l’image, produisant une représentation frontale aux dimensions connues et adaptée aux étapes ultérieures de segmentation et de reconnaissance.
:::

