int main() {
    // 1. Coordinates of the target pixel (row, column)
    int r = 600, c = 800;

    // 2. Direct access to pixel values
    unsigned char pixel_cinza = img_gray.at(r, c);
    std::cout << "Pixel alvo (" << r << ", " << c << "):" << std::endl;
    std::cout << "  Tons de cinza (escalar) : " << (int)pixel_cinza << std::endl;
    std::cout << "  Colorido (canais RGB)   : R=" << (int)img.at(r, c, 0) 
              << ", G=" << (int)img.at(r, c, 1) 
              << ", B=" << (int)img.at(r, c, 2) << std::endl;

    // 3. Neighborhood 3x3 around (r, c); the central pixel is placed between brackets
    std::cout << "Matriz de vizinhanca 3x3 (tons de cinza):" << std::endl;
    for (int dy = -1; dy <= 1; dy++) {
        std::string linha = "";
        for (int dx = -1; dx <= 1; dx++) {
            unsigned char v = img_gray.at(r + dy, c + dx);
            if (dy == 0 && dx == 0) {
                linha += "[" + std::to_string((int)v) + "]";
            } else {
                linha += " " + std::to_string((int)v) + " ";
            }
        }
        std::cout << "  " << linha << std::endl;
    }

    // 4. Marks the pixel position with a hollow red square (3 px border) 
    //    on a copy of the image and displays it (equivalent to the matplotlib point).
    mm::Image marcada = img;
    int lado = 20;  // half-side of the square, in pixels
    int esp = 5;    // border thickness

    for (int x = c - lado; x <= c + lado; x++) {
        for (int w = 0; w < esp; w++) {
            marcada.at(r - lado + w, x, 0) = 255;
            marcada.at(r - lado + w, x, 1) = 0;
            marcada.at(r - lado + w, x, 2) = 0;
            marcada.at(r + lado - w, x, 0) = 255;
            marcada.at(r + lado - w, x, 1) = 0;
            marcada.at(r + lado - w, x, 2) = 0;
        }
    }

    for (int y = r - lado; y <= r + lado; y++) {
        for (int w = 0; w < esp; w++) {
            marcada.at(y, c - lado + w, 0) = 255;
            marcada.at(y, c - lado + w, 1) = 0;
            marcada.at(y, c - lado + w, 2) = 0;
            marcada.at(y, c + lado - w, 0) = 255;
            marcada.at(y, c + lado - w, 1) = 0;
            marcada.at(y, c + lado - w, 2) = 0;
        }
    }

    mm::show(marcada, MM_OUT, "Localizacao do pixel (" + std::to_string(r) + ", " + std::to_string(c) + ")");

    return 0;
}

