// Compilar com: g++ -std=c++17 -o simulador simulador.cpp

#include <iostream>
#include <string>
#include <cmath>

// Função para simular a conversão RGB para Grayscale com ponderação perceptual
// Esta função é uma adaptação da lógica do JavaScript para C++
void simularConversaoRGBToGray(int r, int g, int b) {
    // Cálculo dos componentes ponderados
    double pr = 0.299 * r;
    double pg = 0.587 * g;
    double pb = 0.114 * b;

    double total = pr + pg + pb;
    int gray = static_cast<int>(std::round(total));

    // Exibição dos resultados
    std::cout << "=== Simulador EP01_06: Percepção de Cor & Pesos ITU-R BT.601 ===" << std::endl;
    std::cout << "RGB → Grayscale" << std::endl;
    std::cout << "------------------------------------------------" << std::endl;
    std::cout << "Canais de entrada: R=" << r << " G=" << g << " B=" << b << std::endl;
    std::cout << "------------------------------------------------" << std::endl;
    std::cout << "Decomposição da Fórmula:" << std::endl;
    std::cout << "0.299 × " << r << " = " << pr << std::endl;
    std::cout << "0.587 × " << g << " = " << pg << std::endl;
    std::cout << "0.114 × " << b << " = " << pb << std::endl;
    std::cout << "------------------------------------------------" << std::endl;
    std::cout << "Soma: " << total << std::endl;
    std::cout << "Valor arredondado: " << gray << std::endl;
    std::cout << "------------------------------------------------" << std::endl;
    std::cout << "Cor Original RGB: rgb(" << r << "," << g << "," << b << ")" << std::endl;
    std::cout << "Cor Tons de Cinza: rgb(" << gray << "," << gray << "," << gray << ")" << std::endl;

    // Determinar cor do texto para contraste
    std::string corTexto = (gray > 128) ? "#000000" : "#ffffff";
    std::cout << "Cor do texto no display: " << corTexto << std::endl;
    std::cout << "------------------------------------------------" << std::endl;
    std::cout << "Dica: O canal Verde (G) possui o maior peso (0.587)" << std::endl;
    std::cout << "devido à maior sensibilidade espectral do sistema" << std::endl;
    std::cout << "visual humano aos comprimentos de onda do verde." << std::endl;
    std::cout << "================================================" << std::endl;
}

// Função principal para testar a conversão
int main() {
    std::cout << "=== CONVERSÃO RGB PARA GRAYSCALE (ITU-R BT.601) ===" << std::endl;
    std::cout << std::endl;

    // Testes com valores iniciais do simulador
    simularConversaoRGBToGray(80, 180, 30);
    std::cout << std::endl;

    simularConversaoRGBToGray(255, 255, 255);
    std::cout << std::endl;

    simularConversaoRGBToGray(0, 0, 0);
    std::cout << std::endl;

    // Loop interativo para testar outros valores
    char continuar = 's';
    while (continuar == 's' || continuar == 'S') {
        int r, g, b;
        std::cout << "\nDigite valores RGB para testar (intervalo 0-255):" << std::endl;
        std::cout << "Vermelho (R): ";
        std::cin >> r;
        std::cout << "Verde (G): ";
        std::cin >> g;
        std::cout << "Azul (B): ";
        std::cin >> b;

        // Validar entrada
        if (r >= 0 && r <= 255 && g >= 0 && g <= 255 && b >= 0 && b <= 255) {
            std::cout << std::endl;
            simularConversaoRGBToGray(r, g, b);
        } else {
            std::cout << "Valores inválidos! Use valores entre 0 e 255." << std::endl;
        }

        std::cout << "\nContinuar testando? (s/n): ";
        std::cin >> continuar;
    }

    std::cout << "\nSimulador finalizado. Até logo!" << std::endl;
    return 0;
}

