int main() {
    // Patch 5x5 extraído da imagem
    mm::Image patch(5, 5);
    for (int y = 0; y < 5; y++) {
        for (int x = 0; x < 5; x++) {
            patch.at(y, x) = img_gray.at(250 + y, 250 + x);
        }
    }

    // Converte para float para cálculos
    float p[3][3];  // Precisamos apenas da região 3x3 para os cálculos de Sobel
    for (int y = 0; y < 3; y++) {
        for (int x = 0; x < 3; x++) {
            p[y][x] = (float)patch.at(y, x);
        }
    }

    // Gx no pixel [1,1]: coluna direita - coluna esquerda (ponderada)
    float gx = (p[0][2] + 2*p[1][2] + p[2][2]) - (p[0][0] + 2*p[1][0] + p[2][0]);

    // Gy no pixel [1,1]: linha inferior - linha superior (ponderada)
    float gy = (p[2][0] + 2*p[2][1] + p[2][2]) - (p[0][0] + 2*p[0][1] + p[0][2]);

    float mag   = std::sqrt(gx*gx + gy*gy);
    float theta = std::atan2(gy, gx) * 180.0f / M_PI;

    std::cout << "Patch 5x5:" << std::endl;
    std::cout << mm::drawImg(patch) << std::endl;

    std::cout << "Gx em [1,1]: (" << (int)p[0][2] << " + 2*" << (int)p[1][2] 
              << " + " << (int)p[2][2] << ") - (" << (int)p[0][0] 
              << " + 2*" << (int)p[1][0] << " + " << (int)p[2][0] 
              << ") = " << gx << std::endl;

    std::cout << "Gy em [1,1]: (" << (int)p[2][0] << " + 2*" << (int)p[2][1] 
              << " + " << (int)p[2][2] << ") - (" << (int)p[0][0] 
              << " + 2*" << (int)p[0][1] << " + " << (int)p[0][2] 
              << ") = " << gy << std::endl;

    std::cout << "mag(Grad f)  = sqrt(" << gx << "^2 + " << gy 
              << "^2) = " << mag << std::endl;
    std::cout << "Theta        = arctan(" << gy << "/" << gx 
              << ") = " << theta << " graus" << std::endl;

    return 0;
}

