// Compile with: g++ -std=c++17 -I/path/to/morph.hpp -o program program.cpp
#include <iostream>
#include <vector>
#include <algorithm>
#include <numeric>
#include <cmath>

int main() {
    // Exemplo numérico: média vs. mediana com pixel corrompido
    std::vector<int> vizinhanca = {102, 98, 105, 100, 255, 97, 103, 99, 101};

    // Ordenar e imprimir a vizinhança
    std::vector<int> sorted_viz = vizinhanca;
    std::sort(sorted_viz.begin(), sorted_viz.end());
    std::cout << "Vizinhança: [";
    for (size_t i = 0; i < sorted_viz.size(); ++i) {
        if (i > 0) std::cout << ", ";
        std::cout << sorted_viz[i];
    }
    std::cout << "]\n";

    // Calcular a média
    double media = static_cast<double>(std::accumulate(vizinhanca.begin(), vizinhanca.end(), 0)) / vizinhanca.size();
    std::cout << "Média:      " << media << "  (deslocada pelo outlier 255)\n";

    // Calcular a mediana (elemento do meio do vetor ordenado)
    int mediana = sorted_viz[sorted_viz.size() / 2];
    std::cout << "Mediana:    " << mediana << "    (ignora o outlier)\n";
    std::cout << "Valor original:  ~100\n";

    return 0;
}

