#include "morph.hpp"
#include <cmath>
#include <iostream>
#include <vector>
#include <complex>

// Helper function to compute 2D FFT (simplified version)
std::vector<std::vector<std::complex<double>>> fft2(const mm::Image& img) {
    int h = img.h, w = img.w;
    std::vector<std::vector<std::complex<double>>> result(h, std::vector<std::complex<double>>(w));

    // 1D FFT on rows
    for(int y = 0; y < h; y++) {
        std::vector<std::complex<double>> row(w);
        for(int x = 0; x < w; x++) {
            row[x] = (double)img.at(y, x);
        }
        // FFT on row
        int n = w;
        for(int i = 0; i < n; i++) {
            for(int j = 0; j < n; j++) {
                result[y][j] += row[i] * std::polar(1.0, -2.0 * M_PI * i * j / n);
            }
        }
    }

    // 1D FFT on columns
    std::vector<std::vector<std::complex<double>>> final_result(h, std::vector<std::complex<double>>(w));
    for(int x = 0; x < w; x++) {
        std::vector<std::complex<double>> col(h);
        for(int y = 0; y < h; y++) {
            col[y] = result[y][x];
        }
        int n = h;
        for(int i = 0; i < n; i++) {
            for(int j = 0; j < n; j++) {
                final_result[j][x] += col[i] * std::polar(1.0, -2.0 * M_PI * i * j / n);
            }
        }
    }

    return final_result;
}

// Helper function for fftshift
std::vector<std::vector<std::complex<double>>> fftshift2(const std::vector<std::vector<std::complex<double>>>& arr) {
    int h = arr.size(), w = arr[0].size();
    std::vector<std::vector<std::complex<double>>> shifted(h, std::vector<std::complex<double>>(w));

    for(int y = 0; y < h; y++) {
        for(int x = 0; x < w; x++) {
            int new_y = (y + h/2) % h;
            int new_x = (x + w/2) % w;
            shifted[new_y][new_x] = arr[y][x];
        }
    }
    return shifted;
}

int main() {
    // img_sinal1 = np.zeros((128, 128)); img_sinal1[:, 20:25] = 1; img_sinal1[100:105, :] = 1
    mm::Image img_sinal1(128, 128);
    for(int y = 0; y < 128; y++) {
        for(int x = 20; x < 25; x++) {
            img_sinal1.at(y, x) = 1;
        }
    }
    for(int y = 100; y < 105; y++) {
        for(int x = 0; x < 128; x++) {
            img_sinal1.at(y, x) = 1;
        }
    }

    // img_sinal2 = np.zeros((128, 128)); img_sinal2[:, 90:95] = 1; img_sinal2[30:35, :] = 1
    mm::Image img_sinal2(128, 128);
    for(int y = 0; y < 128; y++) {
        for(int x = 90; x < 95; x++) {
            img_sinal2.at(y, x) = 1;
        }
    }
    for(int y = 30; y < 35; y++) {
        for(int x = 0; x < 128; x++) {
            img_sinal2.at(y, x) = 1;
        }
    }

    // mag1 = np.log1p(np.abs(np.fft.fftshift(np.fft.fft2(img_sinal1))))
    auto fft1 = fftshift2(fft2(img_sinal1));
    mm::Image mag1(128, 128);
    for(int y = 0; y < 128; y++) {
        for(int x = 0; x < 128; x++) {
            double abs_val = std::abs(fft1[y][x]);
            mag1.at(y, x) = (unsigned char)(std::log1p(abs_val) * 255.0 / std::log1p(128*128)); // Scale to 0-255
        }
    }

    // mag2 = np.log1p(np.abs(np.fft.fftshift(np.fft.fft2(img_sinal2))))
    auto fft2_arr = fftshift2(fft2(img_sinal2));
    mm::Image mag2(128, 128);
    for(int y = 0; y < 128; y++) {
        for(int x = 0; x < 128; x++) {
            double abs_val = std::abs(fft2_arr[y][x]);
            mag2.at(y, x) = (unsigned char)(std::log1p(abs_val) * 255.0 / std::log1p(128*128)); // Scale to 0-255
        }
    }

    // mm.show([img_sinal1, mag1, img_sinal2, mag2],
    //         titles=["Sinal A", "Espectro A", "Sinal B (Deslocado)", "Espectro B"], 
    //         cols=4, figsize=(14, 4)
    //         )
    std::vector<mm::Image> images = {img_sinal1, mag1, img_sinal2, mag2};
    std::vector<std::string> titles = {"Sinal A", "Espectro A", "Sinal B (Deslocado)", "Espectro B"};
