// Compile: g++ -std=c++17 -O2 programa.cpp -o programa && ./programa
#include <iostream>
#include <vector>
#include <chrono>
#include <sys/resource.h>

// Função que simula a lista de tuplas (i, i)
std::vector<std::pair<int, int>> lista(int n) {
    std::vector<std::pair<int, int>> result;
    result.reserve(n);
    for (int i = 0; i < n; ++i) {
        result.push_back({i, i});
    }
    return result;
}

// Função que simula o gerador (yield i, i)
// No C++, não temos geradores nativamente, então usamos um callback ou iteramos diretamente
template<typename Func>
void gera(int n, Func&& func) {
    for (int i = 0; i < n; ++i) {
        func(i, i);
    }
}

// Mede o pico de memória usando getrusage (RUSAGE_SELF)
size_t getPeakMemory() {
    struct rusage usage;
    getrusage(RUSAGE_SELF, &usage);
    return usage.ru_maxrss; // em kilobytes (Linux) ou bytes (macOS)
}

int main() {
    // Para cada abordagem, medimos o pico de memória
    {
        // LISTA
        auto start = std::chrono::high_resolution_clock::now();
        auto vec = lista(9'000'000);
        long long sum = 0;
        for (const auto& [x, y] : vec) {
            sum += x + y;
        }
        auto end = std::chrono::high_resolution_clock::now();
        std::cout << "LISTA: ";
        std::cout << "pico = " << getPeakMemory() / 1024.0 << " MB, ";
        std::cout << "tempo = " << std::chrono::duration<double>(end - start).count() << " s, ";
        std::cout << "soma = " << sum << " (descartado)\n";
    }

    {
        // YIELD (simulado com callback)
        auto start = std::chrono::high_resolution_clock::now();
        long long sum = 0;
        gera(9'000'000, [&](int x, int y) {
            sum += x + y;
        });
        auto end = std::chrono::high_resolution_clock::now();
        std::cout << "YIELD: ";
        std::cout << "pico = " << getPeakMemory() / 1024.0 << " MB, ";
        std::cout << "tempo = " << std::chrono::duration<double>(end - start).count() << " s, ";
        std::cout << "soma = " << sum << " (descartado)\n";
    }

    return 0;
}

