// Simple helper to fetch URL content (requires curl or wget available)
std::string downloadUrl(const std::string& url) {
    std::string cmd = "curl -s " + url;
    std::string result;
    char buffer[128];
    FILE* pipe = popen(cmd.c_str(), "r");
    if (!pipe) return "";
    while (fgets(buffer, sizeof(buffer), pipe) != NULL) {
        result += buffer;
    }
    pclose(pipe);
    return result;
}

int main() {
    // Fetch the content from the URL
    std::string url = "https://raw.githubusercontent.com/fzampirolli/mctest/master/exam/CVMCTest.py";
    std::string content = downloadUrl(url);

    // Write the content to the file CVMCTest.py
    std::ofstream writefile("CVMCTest.py");
    if (writefile.is_open()) {
        writefile << content;
        writefile.close();
    } else {
        std::cerr << "Error opening file for writing" << std::endl;
        return 1;
    }

    return 0;
}

