<script>
(function(){
  function initSim08Ransac(root){
    if (!root || root.dataset.sim08RansacInit) return;
    root.dataset.sim08RansacInit = "1";

    const canvas = root.querySelector("#sim-08-ransac_canvas");
    const ctx = canvas.getContext("2d");
    const W = canvas.width, H = canvas.height;

    let pontos = [];
    let limiar = 15;
    let modelo = null; // {a, b, inliersIdx, numIter}

    function gerarPontos(){
      const pts = [];
      const a = 0.5, b = 60; // reta y = a*x + b (referência)
      for (let i = 0; i < 30; i++){
        const x = 40 + Math.random() * (W - 80);
        const yIdeal = a * x + b;
        const y = yIdeal + (Math.random() - 0.5) * 20;
        pts.push({x: x, y: Math.min(Math.max(y, 20), H - 20)});
      }
      for (let i = 0; i < 10; i++){
        pts.push({
          x: 40 + Math.random() * (W - 80),
          y: 20 + Math.random() * (H - 40)
        });
      }
      return pts;
    }

    function distPontoReta(px, py, x1, y1, x2, y2){
      const num = Math.abs((y2 - y1) * px - (x2 - x1) * py + x2 * y1 - y2 * x1);
      const den = Math.sqrt((y2 - y1) ** 2 + (x2 - x1) ** 2);
      return den === 0 ? Infinity : num / den;
    }

    function ajustarMinimosQuadrados(indices){
      let somaX = 0, somaY = 0, somaXY = 0, somaXX = 0;
      const n = indices.length;
      indices.forEach(i => {
        const p = pontos[i];
        somaX += p.x; somaY += p.y; somaXY += p.x * p.y; somaXX += p.x * p.x;
      });
      const denom = (n * somaXX - somaX * somaX);
      if (Math.abs(denom) < 1e-6) return null;
      const a = (n * somaXY - somaX * somaY) / denom;
      const b = (somaY - a * somaX) / n;
      return {a: a, b: b};
    }

    function rodarRansac(){
      const numIter = 60;
      let melhorInliers = [];
      let melhorP1 = null, melhorP2 = null;

      for (let it = 0; it < numIter; it++){
        const i1 = Math.floor(Math.random() * pontos.length);
        let i2 = Math.floor(Math.random() * pontos.length);
        while (i2 === i1) i2 = Math.floor(Math.random() * pontos.length);

        const p1 = pontos[i1], p2 = pontos[i2];
        const inliersAtual = [];

        pontos.forEach((p, idx) => {
          const d = distPontoReta(p.x, p.y, p1.x, p1.y, p2.x, p2.y);
          if (d <= limiar) inliersAtual.push(idx);
        });

        if (inliersAtual.length > melhorInliers.length){
          melhorInliers = inliersAtual;
          melhorP1 = p1; melhorP2 = p2;
        }
      }

      const ajuste = ajustarMinimosQuadrados(melhorInliers) ||
        {a: (melhorP2.y - melhorP1.y) / (melhorP2.x - melhorP1.x + 1e-6), b: melhorP1.y};

      modelo = {
        a: ajuste.a, 
        b: ajuste.b,
        inliersIdx: new Set(melhorInliers),
        numIter: numIter
      };

      render();
    }

    function render(){
      ctx.clearRect(0, 0, W, H);

      // Desenhar pontos
      pontos.forEach((p, idx) => {
        let cor = "#8a8371";
        if (modelo){
          cor = modelo.inliersIdx.has(idx) ? "#27ae60" : "#c0392b";
        }
        ctx.beginPath();
        ctx.arc(p.x, p.y, 6, 0, 2 * Math.PI);
        ctx.fillStyle = cor;
        ctx.fill();
        ctx.lineWidth = 1.2;
        ctx.strokeStyle = "#ffffff";
        ctx.stroke();
      });

      // Desenhar reta ajustada
      if (modelo){
        const x0 = 0, x1 = W;
        const y0 = modelo.a * x0 + modelo.b;
        const y1 = modelo.a * x1 + modelo.b;

        ctx.beginPath();
        ctx.moveTo(x0, y0);
        ctx.lineTo(x1, y1);
        ctx.strokeStyle = "#2980b9";
        ctx.lineWidth = 2.5;
        ctx.stroke();

        root.querySelector("#sim-08-ransac_nIn").textContent = modelo.inliersIdx.size;
        root.querySelector("#sim-08-ransac_nOut").textContent = pontos.length - modelo.inliersIdx.size;
        root.querySelector("#sim-08-ransac_nIter").textContent = modelo.numIter;
      } else {
        root.querySelector("#sim-08-ransac_nIn").textContent = "–";
        root.querySelector("#sim-08-ransac_nOut").textContent = "–";
        root.querySelector("#sim-08-ransac_nIter").textContent = "–";
      }

      root.querySelector("#sim-08-ransac_thVal").textContent = limiar;
    }

    root.querySelector("#sim-08-ransac_slider").addEventListener("input", function(ev){
      limiar = parseInt(ev.target.value, 10);
      root.querySelector("#sim-08-ransac_slVal").textContent = limiar;
      if (modelo) rodarRansac();
      else render();
    });

    root.querySelector("#sim-08-ransac_btnRun").addEventListener("click", rodarRansac);

    root.querySelector("#sim-08-ransac_btnNovo").addEventListener("click", function(){
      pontos = gerarPontos();
      modelo = null;
      render();
    });

    pontos = gerarPontos();
    render();
  }

  function tryInitSim08Ransac(){
    var root = document.getElementById("sim-08-ransac");
    if (root) initSim08Ransac(root); else setTimeout(tryInitSim08Ransac, 200);
  }
  tryInitSim08Ransac();
})();
</script>
</div>
