    }

    // 4. Marque la position du pixel avec un carré rouge creux (bordure
    //    de 3 px) sur une copie de l'image et affiche (équivalent du
    //    point matplotlib).
    mm::Image marcada = img;
    int cote = 20;   // demi-côté du carré, en pixels
    int epais = 5;   // épaisseur de la bordure

    for (int x = c - cote; x <= c + cote + 1; x++) {
        for (int w = 0; w < epais; w++) {
            marcada.at(r - cote + w, x, 0) = 255;
            marcada.at(r - cote + w, x, 1) = 0;
            marcada.at(r - cote + w, x, 2) = 0;
            marcada.at(r + cote - w, x, 0) = 255;
            marcada.at(r + cote - w, x, 1) = 0;
            marcada.at(r + cote - w, x, 2) = 0;
        }
    }

    for (int y = r - cote; y <= r + cote + 1; y++) {
        for (int w = 0; w < epais; w++) {
            marcada.at(y, c - cote + w, 0) = 255;
            marcada.at(y, c - cote + w, 1) = 0;
            marcada.at(y, c - cote + w, 2) = 0;
            marcada.at(y, c + cote - w, 0) = 255;
            marcada.at(y, c + cote - w, 1) = 0;
            marcada.at(y, c + cote - w, 2) = 0;
        }
    }

    std::string titre = "Localisation du pixel (" + std::to_string(r) + ", " 
                       + std::to_string(c) + ")";
    mm::show(marcada, MM_OUT, titre);

    return 0;
}

