      </div>

      <!-- Nearest Neighbor -->
      <div style="background:#fafaf7;border:1px solid #e9e3d3;border-radius:12px;padding:12px;text-align:center;flex:2;min-width:200px;overflow-x:auto;">
        <span style="font-size:10px;font-weight:700;color:#2980b9;letter-spacing:.3px;text-transform:uppercase;display:block;margin-bottom:10px;">🔲 Plus proche voisin</span>
