// Compile with: g++ -std=c++17 -I. -o program program.cpp -lm

#include "morph.hpp"
#include <iostream>
#include <vector>
#include <string>
#include <cmath>
#include <algorithm>

// Função auxiliar para simular local_binary_pattern (LBP)
mm::Image local_binary_pattern_uniform(const mm::Image& img, int P, int R) {
    int h = img.h;
    int w = img.w;
    mm::Image result(h, w);

    for (int y = 0; y < h; y++) {
        for (int x = 0; x < w; x++) {
            int center = img.at(y, x);
            int bits = 0;
            int transitions = 0;
            int prev_bit = -1;

            for (int p = 0; p < P; p++) {
                double angle = 2.0 * M_PI * p / P;
                int xo = x + static_cast<int>(R * cos(angle));
                int yo = y + static_cast<int>(R * sin(angle));

                if (xo < 0 || xo >= w || yo < 0 || yo >= h) {
                    bits = (bits << 1) | 0;
                    if (prev_bit != -1 && prev_bit != 0) transitions++;
                    prev_bit = 0;
                    continue;
                }

                int val = img.at(yo, xo);
                int bit = (val >= center) ? 1 : 0;
                bits = (bits << 1) | bit;

                if (prev_bit != -1 && prev_bit != bit) transitions++;
                prev_bit = bit;
            }

            // Uniformity check (at most 2 transitions)
            if (transitions <= 2) {
                result.at(y, x) = static_cast<unsigned char>(bits);
            } else {
                result.at(y, x) = P + 1; // Non-uniform pattern
            }
        }
    }
    return result;
}

// Função para converter LBP para RGB usando colormap nipy_spectral simplificado
mm::Image lbp_to_rgb(const mm::Image& lbp) {
    int h = lbp.h;
    int w = lbp.w;
    mm::Image rgb(h, w, 3);

    // Normalização
    unsigned char min_val = 255, max_val = 0;
    for (int y = 0; y < h; y++) {
        for (int x = 0; x < w; x++) {
            min_val = std::min(min_val, lbp.at(y, x));
            max_val = std::max(max_val, lbp.at(y, x));
        }
    }

    // Colormap simplificado baseado em nipy_spectral
    for (int y = 0; y < h; y++) {
        for (int x = 0; x < w; x++) {
            double norm = (double)(lbp.at(y, x) - min_val) / (max_val - min_val + 1e-8);

            // Aproximação do colormap nipy_spectral
            double r, g, b;
            if (norm < 0.2) {
                r = 0; g = 0; b = 0.5 + 2.5 * norm;
            } else if (norm < 0.4) {
                r = 0; g = 5 * (norm - 0.2); b = 1.0;
            } else if (norm < 0.6) {
                r = 5 * (norm - 0.4); g = 1.0; b = 1.0 - 5 * (norm - 0.4);
            } else if (norm < 0.8) {
                r = 1.0; g = 1.0 - 5 * (norm - 0.6); b = 0;
            } else {
                r = 1.0; g = 0; b = 0;
            }

            rgb.at(y, x, 0) = static_cast<unsigned char>(r * 255);
            rgb.at(y, x, 1) = static_cast<unsigned char>(g * 255);
            rgb.at(y, x, 2) = static_cast<unsigned char>(b * 255);
        }
    }
    return rgb;
}

// Função simplificada para HOG (esboço)
mm::Image hog_visualization(const mm::Image& img) {
    int h = img.h;
    int w = img.w;
    mm::Image result(h, w);

    // Gradiente simples via diferenças
    for (int y = 1; y < h-1; y++) {
        for (int x = 1; x < w-1; x++) {
            int dx = static_cast<int>(img.at(y, x+1)) - static_cast<int>(img.at(y, x-1));
            int dy = static_cast<int>(img.at(y+1, x)) - static_cast<int>(img.at(y-1, x));
            double mag = std::sqrt(dx*dx + dy*dy);
            result.at(y, x) = static_cast<unsigned char>(std::min(mag * 2.0, 255.0));
        }
    }
    return result;
}

int main() {
    // Carregar imagem de exemplo (usando uma imagem sintética para simular camera)
    mm::Image imagem(256, 256);
    // Simular imagem de câmera com padrão
    for (int y = 0; y < 256; y++) {
        for (int x = 0; x < 256; x++) {
            imagem.at(y, x) = static_cast<unsigned char>(
                (x * 0.2 + y * 0.1 + 128 * std::sin(x * 0.05) * std::cos(y * 0.03) + 128)
            );
        }
    }

    // Aplicar descritores
    mm::Image lbp_img = local_binary_pattern_uniform(imagem, 8, 1);

    // Converter o LBP para RGB apenas para facilitar a visualização
    mm::Image lbp_rgb = lbp_to_rgb(lbp_img);

    mm::Image hog_img = hog_visualization(imagem);

    // Exibição padronizada
    mm::show(
        std::vector<mm::Image>{imagem, lbp_rgb, hog_img},
        MM_OUT,
        std::vector<std::string>{
            "Imagem Original\n(como o humano vê)",
            "LBP: Textura\n(cada cor = um código LBP)",
            "HOG: Gradientes e Contornos\n(regiões claras = maior intensidade)"
        },
        3
    );

    std::cout << "Observe como cada descritor destaca propriedades diferentes:" << std::endl;
    std::cout << "• LBP: evidencia padrões locais de textura." << std::endl;
    std::cout << "• HOG: evidencia contornos e orientações das bordas." << std::endl;
    std::cout << "• Imagem original: contém apenas os valores de intensidade." << std::endl;

    return 0;
}

