#include "morph.hpp"
#include <iostream>
#include <string>
#include <filesystem>

//| label: fig-03-mandrill
//| fig-cap: "*Mandrill* (*Mandrillus sphinx*) fotografado em ambiente natural na África do Sul. A imagem possui resolução de 500 px e contém metadados EXIF com coordenadas GPS aproximadas (-26.20473, 28.22662). Crédito: Carlos Guilherme Rodrigues (CC BY-SA 3.0)."
//| echo: true

int main() {
    // Fonte : https://commons.wikimedia.org/wiki/File:Carlos_Guilherme_Rodrigues_(76515283).jpeg
    // Mapa  : https://www.google.com/maps?q=-26.204734,28.226624

    std::string base    = "https://upload.wikimedia.org/wikipedia/commons";
    std::string arquivo = "Carlos_Guilherme_Rodrigues_%2876515283%29.jpeg";
    std::string url     = base + "/9/9b/" + arquivo;
    std::string caminho = "imagens/mandrill-exif.jpg";

    // 1. Leitura com cache local
    mm::Image img_obj;
    if (!std::filesystem::exists(caminho)) {
        std::filesystem::create_directories("imagens");
        img_obj = mm::read(url);
        mm::write(img_obj, caminho);
    } else {
        img_obj = mm::read(caminho);
    }

    mm::Image img_color = img_obj;
    mm::Image img_gray  = mm::gray(img_color);

    // 2. Diagnóstico de tipos, dimensões e acesso a pixels
    std::cout << "\nTipo PIL  : Imagem | Dimensões (x,y): " << img_obj.w << " x " << img_obj.h << "\n";
    std::cout << "Tipo NumPy: Imagem | Dimensões [y,x,c]: " << img_color.h << " x " << img_color.w << " x " << img_color.channels << "\n";

    // 3. Exibição
    mm::show(img_color, MM_OUT);

    return 0;
}

