// Compile with: g++ -std=c++17 -o program program.cpp -I. -lcurl

#include <iostream>
#include <random>
#include <vector>
#include <string>
#include <algorithm>
#include "morph.hpp"

// Note: This code assumes the OxfordIIITPet dataset is available through some mechanism.
// Since this is a Python-specific library (torchvision), we simulate the data loading
// and work with mm::Image directly.

const std::vector<std::string> RACAS_ALVO = {"Pug", "Boxer"};
const int N_TREINO_POR_CLASSE = 15;
const int N_TESTE_POR_CLASSE = 20;

int main() {
    // 1. Download of the complete dataset (37 breeds) - license CC BY-SA 4.0
    // In C++, we assume we have access to the dataset images.
    // For this simulation, we'll use placeholder images.

    // Simulate the two target breeds with their original indices (0 and 1 for simplicity)
    std::vector<int> indices_alvo = {0, 1}; // In a real scenario, these would be the indices of "Pug" and "Boxer"

    // 2. Filtering of the two breeds of interest, separated by class
    // We'll simulate having loaded images for both breeds
    std::vector<std::vector<mm::Image>> por_classe(2);

    // Load 40 images per class (15 training + 20 test + 5 extra)
    for (int classe = 0; classe < 2; ++classe) {
        for (int i = 0; i < N_TREINO_POR_CLASSE + N_TESTE_POR_CLASSE + 5; ++i) {
            // Create a dummy image (e.g., 64x64 RGB)
            mm::Image img(64, 64, 3);
            // Fill with some dummy data
            for (int y = 0; y < 64; ++y) {
                for (int x = 0; x < 64; ++x) {
                    img.at(y, x, 0) = static_cast<unsigned char>((i * 7 + x + classe * 5) % 256);
                    img.at(y, x, 1) = static_cast<unsigned char>((i * 13 + y + classe * 11) % 256);
                    img.at(y, x, 2) = static_cast<unsigned char>((i * 17 + x + y + classe * 3) % 256);
                }
            }
            por_classe[classe].push_back(img);
        }
    }

    // 3. Sampling: few training images, more test images
    std::mt19937 rng(42); // Fixed seed for reproducibility
    std::vector<mm::Image> imgs_treino, imgs_teste;
    std::vector<int> y_treino, y_teste;

    for (int classe_idx = 0; classe_idx < static_cast<int>(indices_alvo.size()); ++classe_idx) {
        std::vector<mm::Image> imgs_raca = por_classe[classe_idx];

        // Shuffle the images for this breed
        std::shuffle(imgs_raca.begin(), imgs_raca.end(), rng);

        // Training images
        for (int i = 0; i < N_TREINO_POR_CLASSE; ++i) {
            imgs_treino.push_back(imgs_raca[i]);
            y_treino.push_back(classe_idx);
        }

        // Test images
        for (int i = N_TREINO_POR_CLASSE; i < N_TREINO_POR_CLASSE + N_TESTE_POR_CLASSE; ++i) {
            imgs_teste.push_back(imgs_raca[i]);
            y_teste.push_back(classe_idx);
        }
    }

    std::cout << "Training: " << imgs_treino.size() << " images | Test: " << imgs_teste.size() << " images\n";

    // Select sample images for display: 4 from first breed and 4 from second breed
    std::vector<mm::Image> amostras_exibicao;
    for (int i = 0; i < 4; ++i) {
        amostras_exibicao.push_back(imgs_treino[i]);
        amostras_exibicao.push_back(imgs_treino[N_TREINO_POR_CLASSE + i]);
    }

    std::vector<std::string> titulos_exibicao;
    for (int i = 0; i < 4; ++i) titulos_exibicao.push_back(RACAS_ALVO[0]);
    for (int i = 0; i < 4; ++i) titulos_exibicao.push_back(RACAS_ALVO[1]);

    mm::show(amostras_exibicao, MM_OUT, titulos_exibicao, 4);

    return 0;
}

