              cm.style.boxShadow = 'none';
              cm.style.background = 'rgb(' + mgv + ',' + mgv + ',' + mgv + ')';
              cm.style.color = textColor(mgv);
              resetDebug();
            });
          })(r, c, gx, gy, mag);
        }
        gridM.appendChild(cm);
      }
    }

    btnNew.addEventListener('click', function(){
