#include "morph.hpp"
#include <iostream>
#include <string>

int main() {
    // img and img_gray are provided as already-valid variables

    // 1. Coordenadas do pixel alvo (linha, coluna)
    int r = 600, c = 800;

    // 2. Acesso direto aos valores do pixel
    unsigned char pixel_cinza = img_gray.at(r, c);
    std::cout << "Pixel alvo (" << r << ", " << c << "):" << std::endl;
    std::cout << "  Tons de cinza (escalar) : " << (int)pixel_cinza << std::endl;
    std::cout << "  Colorido (canais RGB)   : R=" << (int)img.at(r, c, 0) 
              << ", G=" << (int)img.at(r, c, 1) 
              << ", B=" << (int)img.at(r, c, 2) << std::endl;

    // 3. Vizinhanca 3x3 ao redor de (r, c); o pixel central vai entre colchetes
    std::cout << "Matriz de vizinhanca 3x3 (tons de cinza):" << std::endl;
    for (int dy = -1; dy <= 1; dy++) {
        std::string linha = "";
        for (int dx = -1; dx <= 1; dx++) {
            int v = (int)img_gray.at(r + dy, c + dx);
            // Formatação com 3 espaços, alinhamento à direita
            if (dy == 0 && dx == 0) {
                char buffer[20];
                snprintf(buffer, sizeof(buffer), "[%3d]", v);
                linha += buffer;
            } else {
                char buffer[20];
                snprintf(buffer, sizeof(buffer), " %3d ", v);
                linha += buffer;
            }
        }
        std::cout << "  " << linha << std::endl;
    }

    // 4. Marca a posicao do pixel com um quadrado vermelho vazado (borda de
    //    3 px) numa copia da imagem e exibe (equivalente ao ponto do matplotlib).
    mm::Image marcada = img;
    int lado = 60;   // meio-lado do quadrado, em pixels
    int esp = 3;     // espessura da borda

    // Bordas horizontais (topo e base)
    for (int x = c - lado; x <= c + lado; x++) {
        for (int w = 0; w < esp; w++) {
            // Topo
            marcada.at(r - lado + w, x, 0) = 255;
            marcada.at(r - lado + w, x, 1) = 0;
            marcada.at(r - lado + w, x, 2) = 0;
            // Base
            marcada.at(r + lado - w, x, 0) = 255;
            marcada.at(r + lado - w, x, 1) = 0;
            marcada.at(r + lado - w, x, 2) = 0;
        }
    }

    // Bordas verticais (esquerda e direita)
    for (int y = r - lado; y <= r + lado; y++) {
        for (int w = 0; w < esp; w++) {
            // Esquerda
            marcada.at(y, c - lado + w, 0) = 255;
            marcada.at(y, c - lado + w, 1) = 0;
            marcada.at(y, c - lado + w, 2) = 0;
            // Direita
            marcada.at(y, c + lado - w, 0) = 255;
            marcada.at(y, c + lado - w, 1) = 0;
            marcada.at(y, c + lado - w, 2) = 0;
        }
    }

    std::string titulo = "Localizacao do pixel (" + std::to_string(r) + ", " + std::to_string(c) + ")";
    mm::show(marcada, MM_OUT, titulo);

    return 0;
}

