// Função que calcula a distância de Hamming entre dois inteiros
int hamming(int a, int b) {
    return __builtin_popcount(a ^ b);
}

int main() {
    int a = 0b01000000001000110110011111101010;
    int b = 0b10110000001011100100111111100010;
    int result = hamming(a, b);
    std::cout << result << "\n";
    return 0;
}

