#include <iostream>
#include <chrono>
#include <vector>
#include <cstdint>
#include <string>

// Simulating tracemalloc using memory measurement (e.g., /proc/self/status on Linux)
// Note: Actual tracemalloc equivalent requires OS-specific APIs.

#ifdef __linux__
#include <fstream>
#include <sstream>

size_t getCurrentRSS() {
    std::ifstream status("/proc/self/status");
    std::string line;
    while (std::getline(status, line)) {
        if (line.rfind("VmRSS:", 0) == 0) {
            std::istringstream iss(line.substr(6));
            size_t kb;
            iss >> kb;
            return kb * 1024;
        }
    }
    return 0;
}
#endif

template<typename Func>
void measure(const std::string& name, Func f) {
#ifdef __linux__
    size_t before = getCurrentRSS();
    auto start = std::chrono::high_resolution_clock::now();
    f();
    auto end = std::chrono::high_resolution_clock::now();
    size_t after = getCurrentRSS();
    double peak = (after > before ? after - before : 0) / (1024.0 * 1024.0);
    std::cout << name << ": " << peak << " MB" << std::endl;
#else
    std::cout << name << ": (RSS measurement only available on Linux)" << std::endl;
#endif
}

int main() {
    // Lista: generates a vector of pairs
    auto lista = [](int n) {
        std::vector<std::pair<int, int>> v;
        v.reserve(n);
        for (int i = 0; i < n; ++i) v.emplace_back(i, i);
        return v;
    };

    // Generador: simulates a generator using a struct with iterator
    struct Gera {
        int n;
        int current;
        Gera(int n_) : n(n_), current(0) {}

        // Simple iteration to mimic yield
        bool next(int& a, int& b) {
            if (current < n) {
                a = current;
                b = current;
                ++current;
                return true;
            }
            return false;
        }
    };

    // Simulate both approaches
    struct TestData {
        std::string name;
        bool isList;
    };

    std::vector<TestData> tests = {{"LISTA", true}, {"YIELD", false}};

    for (auto& test : tests) {
        std::string name = test.name;
        bool isList = test.isList;

        measure(name, [&]() {
            if (isList) {
                auto v = lista(9000000);
                long long sum = 0;
                for (auto& p : v) sum += p.first + p.second;
            } else {
                Gera g(9000000);
                long long sum = 0;
                int x, y;
                while (g.next(x, y)) sum += x + y;
            }
        });
    }

    return 0;
}

