#include "morph.hpp"
#include <iostream>
#include <vector>
#include <string>
#include <cmath>
#include <algorithm>

// Função para quantizar a imagem
std::pair<mm::Image, std::string> quantize_simple(const mm::Image& image, int bits) {
    // Reduz a profundidade de bits e calcula metadados de memória
    int levels = std::pow(2, bits);

    // Normalização e quantização uniforme
    mm::Image quantized(image.h, image.w);
    for (int y = 0; y < image.h; ++y) {
        for (int x = 0; x < image.w; ++x) {
            // Para imagens em tons de cinza (1 canal) ou coloridas (3 canais)
            for (int c = 0; c < image.channels; ++c) {
                int val = image.at(y, x, c);
                int new_val = static_cast<int>(std::floor(val / 256.0 * levels) / levels * 255);
                quantized.at(y, x, c) = static_cast<unsigned char>(new_val);
            }
        }
    }

    // Se a imagem original era em tons de cinza (1 canal), converter para 3 canais para exibição
    if (image.channels == 1) {
        mm::Image quantized_rgb(quantized.h, quantized.w);
        for (int y = 0; y < quantized.h; ++y) {
            for (int x = 0; x < quantized.w; ++x) {
                unsigned char v = quantized.at(y, x, 0);
                quantized_rgb.at(y, x, 0) = v;
                quantized_rgb.at(y, x, 1) = v;
                quantized_rgb.at(y, x, 2) = v;
            }
        }
        quantized = quantized_rgb;
    }

    // Cálculo de memória em KB
    double mem_kb = quantized.h * quantized.w * quantized.channels / 1024.0;
    std::string label = std::to_string(bits) + " bits (" + std::to_string(levels) + " níveis)\n" + 
                        std::to_string(static_cast<int>(mem_kb)) + " KB";

    return {quantized, label};
}

int main() {
    // A imagem de entrada (img_gray) deve ser carregada previamente
    // Assumindo que img_gray está disponível (carregada como escala de cinza)
    mm::Image img_gray = mm::read("sua_imagem.png", true); // Substitua pelo caminho real

    // Lista de bits para teste (8 é o padrão, 1 é o binário)
    std::vector<int> bits_test = {8, 4, 2, 1};

    // Gera os resultados e separa em listas para o mm.show
    std::vector<mm::Image> imgs_q;
    std::vector<std::string> titles_q;

    for (int b : bits_test) {
        auto result = quantize_simple(img_gray, b);
        imgs_q.push_back(result.first);
        titles_q.push_back(result.second);
    }

    mm::show(imgs_q, MM_OUT, titles_q, 4);

    return 0;
}

