        for (int y = 0; y < 8; ++y) {
            for (int x = 0; x < 8; ++x) {
                img.at(y, x) = static_cast<unsigned char>(pixelDist(gen));
            }
        }
        dataset.images.push_back(img);
        dataset.targets.push_back(i % 10);  // dígitos 0-9
    }

    // Normalização para a faixa [0, 1]
    std::vector<mm::Image> X;
    for (const auto& img : dataset.images) {
        X.push_back(normalizeImage(img));
