#include <iostream>
#include <vector>
#include <cmath>
#include <random>
#include <algorithm>

// Simple CNN implementation in C++
// This is a simplified version of the PyTorch CNN for digit classification

class Conv2d {
public:
    int in_channels, out_channels, kernel_size, padding;
    std::vector<std::vector<std::vector<std::vector<double>>>> weights;
    std::vector<double> bias;

    Conv2d(int in_ch, int out_ch, int k_size, int pad = 0) 
        : in_channels(in_ch), out_channels(out_ch), kernel_size(k_size), padding(pad) {
        // Initialize weights with small random values
        std::random_device rd;
        std::mt19937 gen(rd());
        std::normal_distribution<double> dist(0.0, 0.1);

        weights.resize(out_channels);
        for (auto& oc : weights) {
            oc.resize(in_channels);
            for (auto& ic : oc) {
                ic.resize(kernel_size);
                for (auto& k : ic) {
                    k.resize(kernel_size);
                    for (auto& val : k) {
                        val = dist(gen);
                    }
                }
            }
        }
        bias.resize(out_channels, 0.0);
    }

    std::vector<std::vector<std::vector<double>>> forward(
        const std::vector<std::vector<std::vector<double>>>& input) {
        int input_h = input[0].size();
        int input_w = input[0][0].size();
        int output_h = input_h + 2 * padding - kernel_size + 1;
        int output_w = input_w + 2 * padding - kernel_size + 1;

        std::vector<std::vector<std::vector<double>>> output(
            out_channels, std::vector<std::vector<double>>(output_h, std::vector<double>(output_w, 0.0)));

        for (int oc = 0; oc < out_channels; oc++) {
            for (int oh = 0; oh < output_h; oh++) {
                for (int ow = 0; ow < output_w; ow++) {
                    double sum = bias[oc];
                    for (int ic = 0; ic < in_channels; ic++) {
                        for (int kh = 0; kh < kernel_size; kh++) {
                            for (int kw = 0; kw < kernel_size; kw++) {
                                int ih = oh + kh - padding;
                                int iw = ow + kw - padding;
                                if (ih >= 0 && ih < input_h && iw >= 0 && iw < input_w) {
                                    sum += input[ic][ih][iw] * weights[oc][ic][kh][kw];
                                }
                            }
                        }
                    }
                    output[oc][oh][ow] = sum;
                }
            }
        }
        return output;
    }
};

class MaxPool2d {
public:
    int pool_size, stride;

    MaxPool2d(int p_size, int str) : pool_size(p_size), stride(str) {}

    std::vector<std::vector<std::vector<double>>> forward(
        const std::vector<std::vector<std::vector<double>>>& input) {
        int channels = input.size();
        int input_h = input[0].size();
        int input_w = input[0][0].size();
        int output_h = (input_h - pool_size) / stride + 1;
        int output_w = (input_w - pool_size) / stride + 1;

        std::vector<std::vector<std::vector<double>>> output(
            channels, std::vector<std::vector<double>>(output_h, std::vector<double>(output_w, 0.0)));

        for (int c = 0; c < channels; c++) {
            for (int oh = 0; oh < output_h; oh++) {
                for (int ow = 0; ow < output_w; ow++) {
                    double max_val = -std::numeric_limits<double>::infinity();
                    for (int ph = 0; ph < pool_size; ph++) {
                        for (int pw = 0; pw < pool_size; pw++) {
                            int ih = oh * stride + ph;
                            int iw = ow * stride + pw;
                            max_val = std::max(max_val, input[c][ih][iw]);
                        }
                    }
                    output[c][oh][ow] = max_val;
                }
            }
        }
        return output;
    }
};

class Linear {
public:
    int in_features, out_features;
    std::vector<std::vector<double>> weights;
    std::vector<double> bias;

    Linear(int in_feat, int out_feat) : in_features(in_feat), out_features(out_feat) {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::normal_distribution<double> dist(0.0, 0.1);

        weights.resize(in_features);
        for (auto& row : weights) {
            row.resize(out_features);
            for (auto& val : row) {
                val = dist(gen);
            }
        }
        bias.resize(out_features, 0.0);
    }

    std::vector<double> forward(const std::vector<double>& input) {
        std::vector<double> output(out_features, 0.0);
        for (int j = 0; j < out_features; j++) {
            output[j] = bias[j];
            for (int i = 0; i < in_features; i++) {
                output[j] += input[i] * weights[i][j];
            }
        }
        return output;
    }
};

class ReLU {
public:
    std::vector<std::vector<std::vector<double>>> forward(
        const std::vector<std::vector<std::vector<double>>>& input) {
        auto output = input;
        for (auto& channel : output) {
            for (auto& row : channel) {
                for (auto& val : row) {
                    val = std::max(0.0, val);
                }
            }
        }
        return output;
    }

    std::vector<double> forward(const std::vector<double>& input) {
        std::vector<double> output = input;
        for (auto& val : output) {
            val = std::max(0.0, val);
        }
        return output;
    }
};

class CNNDigitos {
public:
    int n_classes;
    Conv2d conv1;
    Conv2d conv2;
    ReLU relu;
    MaxPool2d pool;
    Linear fc1;
    Linear fc2;

    CNNDigitos(int n_classes = 10) 
        : n_classes(n_classes),
          conv1(1, 8, 3, 1),   // Conv1: 1->8 channels, 3x3 kernel, padding 1
          conv2(8, 16, 3, 1),  // Conv2: 8->16 channels, 3x3 kernel, padding 1
          pool(2, 2),          // MaxPool 2x2, stride 2
          fc1(16 * 2 * 2, 32), // FC1: 64 -> 32
          fc2(32, n_classes)   // FC2: 32 -> n_classes
    {}

    std::vector<double> forward(const std::vector<std::vector<std::vector<double>>>& x) {
        // First block: Conv (8x8) -> ReLU -> Pool (4x4)
        auto x1 = conv1.forward(x);
        x1 = relu.forward(x1);
        x1 = pool.forward(x1);

        // Second block: Conv (4x4) -> ReLU -> Pool (2x2)
        auto x2 = conv2.forward(x1);
        x2 = relu.forward(x2);
        x2 = pool.forward(x2);

        // Flatten: reshape (16, 2, 2) to 1D vector (64)
        std::vector<double> flattened;
        for (const auto& channel : x2) {
            for (const auto& row : channel) {
                for (double val : row) {
                    flattened.push_back(val);
                }
            }
        }

        // Intermediate dense layer with ReLU
        auto x3 = fc1.forward(flattened);
        x3 = relu.forward(x3);

        // Final classification layer (logits)
        return fc2.forward(x3);
    }
};

int main() {
    // Example usage
    CNNDigitos model(10);

    // Create a dummy input (1 channel, 28x28)
    std::vector<std::vector<std::vector<double>>> input(
        1, std::vector<std::vector<double>>(28, std::vector<double>(28, 0.0)));

    // Forward pass
    std::vector<double> output = model.forward(input);

    std::cout << "Output size: " << output.size() << "\n";
    for (size_t i = 0; i < output.size(); i++) {
        std::cout << "logit[" << i << "] = " << output[i] << "\n";
    }

    return 0;
}

