// Compile with: g++ -std=c++17 -o programa programa.cpp -I/path/to/morph/include

#include "morph.hpp"
#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
#include <random>
#include <optional>

// Nota: Este código simula a lógica do simulador HTML em C++
// A interface gráfica não pode ser replicada em C++ diretamente,
// então simulamos os pixels e a transformação.

mm::Image aplicarRemapeamentoCondicional(const mm::Image& entrada, int T, int d1, int d2) {
    mm::Image saida(entrada.h, entrada.w);

    for (int y = 0; y < entrada.h; y++) {
        for (int x = 0; x < entrada.w; x++) {
            int p = entrada.at(y, x, 0);
            int delta = (p < T) ? d1 : d2;
            int res = p + delta;

            // Saturação para 0-255
            res = std::max(0, std::min(255, res));
            saida.at(y, x, 0) = static_cast<unsigned char>(res);
        }
    }

    return saida;
}

void imprimirImagemASCII(const mm::Image& img, const std::string& titulo) {
    std::cout << "\n=== " << titulo << " ===\n";
    std::cout << "Tamanho: " << img.w << "x" << img.h << "\n";

    for (int y = 0; y < img.h; y++) {
        for (int x = 0; x < img.w; x++) {
            int v = img.at(y, x, 0);
            // Representação visual do pixel
            if (v < 64) std::cout << " ";
            else if (v < 128) std::cout << ".";
            else if (v < 192) std::cout << "*";
            else std::cout << "#";
        }
        std::cout << "\n";
    }
}

int main() {
    // Parâmetros do simulador
    int T = 128;    // Limiar
    int d1 = 60;    // Delta para pixels escuros
    int d2 = -40;   // Delta para pixels claros

    // Criar imagem de exemplo 4x4 com valores aleatórios
    mm::Image entrada = mm::randomImage(4, 6, 255);

    std::cout << "=== Simulador EP01_08: Remapeamento por Faixa Condicional ===\n";
    std::cout << "Parâmetros:\n";
    std::cout << "  T (Limiar) = " << T << "\n";
    std::cout << "  δ₁ (Escuros, p < T) = " << d1 << "\n";
    std::cout << "  δ₂ (Claros, p ≥ T) = " << d2 << "\n\n";

    // Mostrar imagem original
    imprimirImagemASCII(entrada, "Entrada Original");

    // Aplicar remapeamento condicional
    mm::Image resultado = aplicarRemapeamentoCondicional(entrada, T, d1, d2);

    // Mostrar resultado
    imprimirImagemASCII(resultado, "Resultado Transformado");

    // Explicação da regra
    std::cout << "\nRegra ativa: p < " << T << " → p + (" << d1 
              << ") | p ≥ " << T << " → p + (" << d2 << ")\n";

    // Mostrar valores detalhados
    std::cout << "\n=== Valores detalhados ===\n";
    for (int y = 0; y < entrada.h; y++) {
        for (int x = 0; x < entrada.w; x++) {
            int p = entrada.at(y, x, 0);
            int delta = (p < T) ? d1 : d2;
            int res_bruto = p + delta;
            int res_sat = std::max(0, std::min(255, res_bruto));

            std::cout << "Pixel[" << y << "," << x << "]: p=" << p 
                      << " → (p " << (p < T ? "<" : "≥") << " " << T 
                      << ") → δ=" << delta 
                      << " → res=" << res_sat
                      << (res_bruto != res_sat ? " [SATURADO]" : "") << "\n";
        }
    }

    return 0;
}

