    std::uniform_real_distribution<> dis(0, 1);
    for (auto& val : result) val = dis(gen);
    return result;
}

// Rotation générique d'entraînement avec optimisation sélective des paramètres
template<typename Modele, typename Optimiseur, typename Perte, typename XType, typename YType>
void entrainer(Modele& modele, XType& X_t, YType& y_t, int epoches, double taux_app, int taille_lot = 16) {
    // Création de l'optimiseur Adam (à adapter)
    Optimiseur optim(&modele, taux_app);
    Perte crit; // Fonction de perte

    int n_echantillons = X_t.size();
    std::vector<int> indices(n_echantillons);
    std::iota(indices.begin(), indices.end(), 0);

    for (int epoch = 0; epoch < epoches; ++epoch) {
        // Mélange aléatoire des échantillons
        std::mt19937 gen(epoch);
        std::shuffle(indices.begin(), indices.end(), gen);

        // Parcours des mini-lots
        for (int i = 0; i < n_echantillons; i += taille_lot) {
            int fin = std::min(i + taille_lot, n_echantillons);
            // Création du lot de données (à adapter)
            std::vector<float> lot_X(X_t.begin() + i, X_t.begin() + fin);
            std::vector<float> lot_y(y_t.begin() + i, y_t.begin() + fin);

            optim.remoindre_gradients(); // Réinitialise les gradients
            // Calcul de la perte (à adapter)
            auto predictions = modele.forward(lot_X);
            double perte = crit(predictions, lot_y); // à adapter
            // Rétropropagation et mise à jour des poids (à adapter)
            optim.step();
        }
    }
}

