// Compile: g++ -std=c++17 -o program program.cpp -I./include

#include <iostream>
#include <string>
#include <vector>
#include <cmath>
#include <algorithm>
#include <functional>

// Simulação da estrutura HTML/JS como representação textual
// Nota: Este código C++ representa a lógica e estrutura do simulador EP01_01

// Estrutura para representar um ponto no plano cartesiano
struct Ponto {
    double x, y;

    Ponto(double px = 0, double py = 0) : x(px), y(py) {}
};

// Estrutura para representar os controles numéricos e sliders
struct Controle {
    double valor;
    double min, max, step;

    Controle(double v = 0, double mn = -7, double mx = 7, double st = 0.5) 
        : valor(v), min(mn), max(mx), step(st) {}
};

// Estrutura principal do simulador
class SimuladorEP0101 {
private:
    // Dimensões do canvas
    static const int canvasWidth = 380;
    static const int canvasHeight = 280;

    // Limites do mundo
    double xMin = -6.5, xMax = 7.8;
    double yMin = -5.2, yMax = 7.2;

    // Pontos A e B
    Ponto pontoA, pontoB;

    // Controles
    Controle ax, ay, bx, by;

    // Valores exibidos
    double distanciaEuclidiana, distanciaCityBlock, distanciaChessboard;

    // Estado de arrasto
    std::string arrastando = "";

public:
    SimuladorEP0101() {
        // Valores iniciais
        pontoA = Ponto(0, 0);
        pontoB = Ponto(3, 4);

        ax = Controle(0); ay = Controle(0);
        bx = Controle(3); by = Controle(4);

        atualizarTudo();
    }

    // Conversão mundo->canvas
    Ponto mundoParaCanvas(double x, double y) {
        double px = ((x - xMin) / (xMax - xMin)) * canvasWidth;
        double py = canvasHeight - ((y - yMin) / (yMax - yMin)) * canvasHeight;
        return Ponto(px, py);
    }

    // Conversão canvas->mundo
    Ponto canvasParaMundo(double px, double py) {
        double x = xMin + (px / canvasWidth) * (xMax - xMin);
        double y = yMin + ((canvasHeight - py) / canvasHeight) * (yMax - yMin);
        return Ponto(x, y);
    }

    // Obter valores atuais dos pontos
    void obterValores() {
        pontoA.x = ax.valor;
        pontoA.y = ay.valor;
        pontoB.x = bx.valor;
        pontoB.y = by.valor;
    }

    // Atualizar todos os valores e cálculos
    void atualizarTudo() {
        obterValores();

        double dx = pontoB.x - pontoA.x;
        double dy = pontoB.y - pontoA.y;

        // Calcular as três métricas de distância
        distanciaEuclidiana = std::hypot(dx, dy);
        distanciaCityBlock = std::abs(dx) + std::abs(dy);
        distanciaChessboard = std::max(std::abs(dx), std::abs(dy));

        desenharCanvas();
    }

    // Função para desenhar o canvas (simulação textual)
    void desenharCanvas() {
        std::cout << "\n=== Simulador EP01_01: Métricas de Distância ===\n";
        std::cout << "Ponto A: (" << pontoA.x << ", " << pontoA.y << ")\n";
        std::cout << "Ponto B: (" << pontoB.x << ", " << pontoB.y << ")\n\n";

        std::cout << "Distâncias:\n";
        std::cout << "  📐 Euclidiana (L2): " << formatarNumero(distanciaEuclidiana) << "\n";
        std::cout << "  🧱 City-block (L1): " << formatarNumero(distanciaCityBlock) << "\n";
        std::cout << "  🏁 Chessboard (L∞): " << formatarNumero(distanciaChessboard) << "\n\n";

        desenharGrade();
        desenharCaminhos();
    }

    std::string formatarNumero(double valor) {
        char buffer[32];
        snprintf(buffer, sizeof(buffer), "%.2f", valor);
        return std::string(buffer);
    }

    // Desenhar grade discreta
    void desenharGrade() {
        std::cout << "Grade Cartesiana:\n";
        for (int i = -6; i <= 7; i++) {
            std::cout << "  ";
            for (int j = -6; j <= 8; j++) {
                bool temA = (j == pontoA.x && i == pontoA.y);
                bool temB = (j == pontoB.x && i == pontoB.y);

                if (temA) std::cout << "A ";
                else if (temB) std::cout << "B ";
                else if (j == 0 && i == 0) std::cout << "+ ";
                else if (j == 0) std::cout << "| ";
                else if (i == 0) std::cout << "──";
                else std::cout << ". ";
            }
            std::cout << "\n";
        }
        std::cout << "\n";
    }

    // Desenhar caminhos das métricas
    void desenharCaminhos() {
        double dx = pontoB.x - pontoA.x;
        double dy = pontoB.y - pontoA.y;

        std::cout << "Caminhos:\n";
        std::cout << "  ── Chessboard (L∞) - Lado Máximo: ";
        if (std::abs(dx) >= std::abs(dy)) {
            std::cout << "Horizontal (" << std::abs(dx) << " unidades)\n";
        } else {
            std::cout << "Vertical (" << std::abs(dy) << " unidades)\n";
        }

        std::cout << "  ── City-block (L1) - Trajeto Ortogonal: ";
        std::cout << std::abs(dx) << " + " << std::abs(dy) << " = " 
                  << (std::abs(dx) + std::abs(dy)) << " unidades\n";

        std::cout << "  ── Euclidiana (L2) - Reta Direta: ";
        std::cout << std::hypot(dx, dy) << " unidades\n\n";
    }

    // Atualizar controle via input numérico
    void atualizarControle(Controle& ctrl, double novoValor) {
        ctrl.valor = novoValor;
        atualizarTudo();
    }

    // Atualizar via slider (com snapping)
    void atualizarSlider(Controle& ctrl, double sliderPos) {
        ctrl.valor = sliderPos;
        atualizarTudo();
    }

    // Reset para valores iniciais
    void reset() {
        pontoA = Ponto(0, 0);
        pontoB = Ponto(3, 4);

        ax.valor = 0; ay.valor = 0;
        bx.valor = 3; by.valor = 4;

        atualizarTudo();
        std::cout << "⟳ Reset A(0,0) & B(3,4) executado\n\n";
    }

    // Processar clique no canvas
    void processarClique(double mouseX, double mouseY) {
        Ponto coords = canvasParaMundo(mouseX, mouseY);

        // Verificar proximidade aos pontos
        Ponto canvasA = mundoParaCanvas(pontoA.x, pontoA.y);
        Ponto canvasB = mundoParaCanvas(pontoB.x, pontoB.y);

        double distA = std::hypot(canvasA.x - mouseX, canvasA.y - mouseY);
        double distB = std::hypot(canvasB.x - mouseX, canvasB.y - mouseY);

        if (distA < 16) {
            arrastando = "A";
            std::cout << "Arrastando ponto A...\n";
        } else if (distB < 16) {
            arrastando = "B";
            std::cout << "Arrastando ponto B...\n";
        }
    }

    // Processar movimento do mouse
    void processarMovimento(double mouseX, double mouseY) {
        if (arrastando.empty()) return;

        Ponto w = canvasParaMundo(mouseX, mouseY);
        w.x = std::round(std::min(xMax - 0.2, std::max(xMin + 0.2, w.x)) * 2) / 2;
        w.y = std::round(std::min(yMax - 0.2, std::max(yMin + 0.2, w.y)) * 2) / 2;

        if (arrastando == "A") {
            ax.valor = w.x; ay.valor = w.y;
        } else {
            bx.valor = w.x; by.valor = w.y;
        }
        atualizarTudo();
    }

    // Soltar ponto
    void soltarPonto() {
        arrastando = "";
    }

    // Interface interativa
    void executarInterface() {
        std::string comando;
        while (true) {
            std::cout << "\nComandos: [R]eset | [M]over A | [N]umber | [Q]uit\n";
            std::cout << "> ";
            std::cin >> comando;

            if (comando == "Q" || comando == "q") break;
            else if (comando == "R" || comando == "r") reset();
            else if (comando == "M" || comando == "m") {
                std::cout << "Mover ponto (A ou B): ";
                std::cin >> comando;
                std::cout << "Nova posição (x y): ";
                double x, y;
                std::cin >> x >> y;

                if (comando == "A" || comando == "a") {
                    atualizarControle(ax, x);
                    atualizarControle(ay, y);
                } else if (comando == "B" || comando == "b") {
                    atualizarControle(bx, x);
                    atualizarControle(by, y);
                }
                atualizarTudo();
            }
            else if (comando == "N" || comando == "n") {
                std::cout << "Entrada numérica:\n";
                std::cout << "  Ax: "; std::cin >> ax.valor;
                std::cout << "  Ay: "; std::cin >> ay.valor;
                std::cout << "  Bx: "; std::cin >> bx.valor;
                std::cout << "  By: "; std::cin >> by.valor;
                atualizarTudo();
            }
        }
    }
};

int main() {
    // Cria o simulador
    SimuladorEP0101 sim;

    std::cout << "🎮 Simulador EP01_01: Métricas de Distância no Espaço Discreto\n";
    std::cout << "Euclidiana vs City-block vs Chessboard\n\n";

    // Mostra o estado inicial
    sim.atualizarTudo();

    // Executa a interface interativa
    sim.executarInterface();

    return 0;
}

cdd83b27f8aa916a86bd09f321ce4899:
## Seuilletage

Le **seuilletage** (*thresholding*) est l'une des formes les plus simples et efficaces de segmentation d'images. Son objectif est de classer chaque pixel en deux classes d'intensité, généralement associées à *objet* et *fond* :

$$
g(x,y) =
\begin{cases}
255, & \text{si } f(x,y) > T \\
0,   & \text{sinon}
\end{cases}
$$ {#eq-04-limiar}

où $f(x,y)$ représente l'intensité du pixel dans l'image originale et $g(x,y)$ l'image binaire résultante.

Le choix du seuil $T$ est important pour la qualité de la segmentation. La méthode d'**Otsu** détermine automatiquement le seuil optimal en maximisant la **variance interclasses** $\sigma_B^2$ définie par :

$$
\sigma_B^2(T) =
w_0(T)\,w_1(T)\,
\bigl[\mu_0(T)-\mu_1(T)\bigr]^2
$$ {#eq-04-otsu}

où :

- $w_0(T)$ et $w_1(T)$ sont les probabilités cumulées des classes fond et objet ;
- $\mu_0(T)$ et $\mu_1(T)$ sont les moyennes d'intensité de ces classes ;
- $\sigma_B^2(T)$ représente la variance interclasses pour un seuil donné $T$.

La méthode fonctionne mieux lorsque l'histogramme présente deux groupes d'intensités relativement séparés. Pour cela, l'algorithme évalue tous les seuils possibles de l'image — typiquement dans l'intervalle $[0,255]$ pour des images 8 bits — et sélectionne la valeur qui maximise la variance entre classes, notée $\sigma_B^2$ :

$$
T^* =
\arg\max_{T \in [0,255]}
\sigma_B^2(T)
$$

::: {.callout-note}
### Otsu suppose des histogrammes bimodaux {.unnumbered}

La méthode d'Otsu produit de meilleurs résultats lorsque l'histogramme présente deux pics bien définis (*bimodalité*), correspondant au fond et à l'objet. Plus la séparation entre ces pics est grande et plus le maximum de $\sigma_B^2$ est prononcé, plus le seuil obtenu tend à être fiable.

Dans les images avec un éclairage non uniforme ou de multiples régions d'intensité, les techniques de **seuilletage adaptatif** — dans lesquelles le seuil est calculé localement — produisent généralement des segmentations plus robustes.

L'indice $B$ dans $\sigma_B^2$ signifie ***between classes*** (*entre classes*). Ainsi, $\sigma_B^2$ représente la **variance entre les classes** (*between-class variance*).

:::

