#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
#include <cmath>

#include "morph.hpp"

// Note: Requires internet access for the first run to download the image
// Compile: g++ -std=c++17 -o fig_02_rgb_rgba fig_02_rgb_rgba.cpp -lm

int main() {
    // https://commons.wikimedia.org/wiki/File:Mandrill-k-means.png
    std::string url = "https://upload.wikimedia.org/wikipedia/commons/a/ab/Mandrill-k-means.png";
    std::string caminho = "imagens/mandrill.png";

    // ── Leitura RGB ───────────────────────────────────────────────────────────────
    // Note: mm::read downloads the image if the file doesn't exist
    // We'll check if the file exists first (using a simple approach)
    mm::Image img_rgb_img;

    // Try to read the file; if it fails, download it
    try {
        img_rgb_img = mm::read(caminho);
    } catch (...) {
        // Download the image
        img_rgb_img = mm::read(url);
        mm::write(img_rgb_img, caminho);
    }

    // The image from mm::read is already RGB (3 channels)
    mm::Image img_rgb = img_rgb_img;

    // ── Criação do canal alfa (gradiente horizontal) ──────────────────────────────
    int h = img_rgb.h;
    int w = img_rgb.w;

    // Create alpha channel as a horizontal gradient
    mm::Image alpha(h, w);

    // Check if the image is grayscale or RGB
    int channels = img_rgb.channels;
    if (channels == 1) {
        // Convert grayscale to RGB first
        img_rgb = mm::gray(img_rgb);  // This won't work as expected, so let's handle it differently
    }

    // Re-read channels after potential conversion
    channels = img_rgb.channels;
    if (channels == 1) {
        // Create an RGB image by replicating channels
        mm::Image img_rgb_new(h, w, 3);
        for (int y = 0; y < h; y++) {
            for (int x = 0; x < w; x++) {
                unsigned char val = img_rgb.at(y, x);
                img_rgb_new.at(y, x, 0) = val;
                img_rgb_new.at(y, x, 1) = val;
                img_rgb_new.at(y, x, 2) = val;
            }
        }
        img_rgb = img_rgb_new;
        channels = 3;
    }

    // Create horizontal gradient for alpha
    for (int y = 0; y < h; y++) {
        for (int x = 0; x < w; x++) {
            alpha.at(y, x) = static_cast<unsigned char>(255.0 * x / (w - 1));
        }
    }

    // Create RGBA image (4 channels)
    mm::Image img_rgba(h, w, 4);
    for (int y = 0; y < h; y++) {
        for (int x = 0; x < w; x++) {
            img_rgba.at(y, x, 0) = img_rgb.at(y, x, 0);
            img_rgba.at(y, x, 1) = img_rgb.at(y, x, 1);
            img_rgba.at(y, x, 2) = img_rgb.at(y, x, 2);
            img_rgba.at(y, x, 3) = alpha.at(y, x);
        }
    }

    // ── Diagnóstico ───────────────────────────────────────────────────────────────
    // Find min/max values
    unsigned char rgb_min = 255, rgb_max = 0;
    unsigned char rgba_min = 255, rgba_max = 0;

    for (int y = 0; y < h; y++) {
        for (int x = 0; x < w; x++) {
            for (int c = 0; c < 3; c++) {
                unsigned char v = img_rgb.at(y, x, c);
                if (v < rgb_min) rgb_min = v;
                if (v > rgb_max) rgb_max = v;
            }
            for (int c = 0; c < 4; c++) {
                unsigned char v = img_rgba.at(y, x, c);
                if (v < rgba_min) rgba_min = v;
                if (v > rgba_max) rgba_max = v;
            }
        }
    }

    std::cout << "RGB   → shape=(" << h << ", " << w << ", 3), dtype=uint8, "
              << "faixa=[" << static_cast<int>(rgb_min) << ", " << static_cast<int>(rgb_max) << "]\n";
    std::cout << "RGBA  → shape=(" << h << ", " << w << ", 4), dtype=uint8, "
              << "faixa=[" << static_cast<int>(rgba_min) << ", " << static_cast<int>(rgba_max) << "]\n";

    // Pixel (0,0)
    std::cout << "Pixel (0,0): RGB=[" 
              << static_cast<int>(img_rgb.at(0, 0, 0)) << ", "
              << static_cast<int>(img_rgb.at(0, 0, 1)) << ", "
              << static_cast<int>(img_rgb.at(0, 0, 2)) << "]  |  RGBA=["
              << static_cast<int>(img_rgba.at(0, 0, 0)) << ", "
              << static_cast<int>(img_rgba.at(0, 0, 1)) << ", "
              << static_cast<int>(img_rgba.at(0, 0, 2)) << ", "
              << static_cast<int>(img_rgba.at(0, 0, 3)) << "]\n";

    // ── Normalização float32 (padrão scikit-image / PyTorch) ──────────────────────
    // Create normalized version
    std::vector<float> img_rgb_norm(h * w * 3);
    float norm_min = 1.0f, norm_max = 0.0f;

    for (int y = 0; y < h; y++) {
        for (int x = 0; x < w; x++) {
            for (int c = 0; c < 3; c++) {
                float v = static_cast<float>(img_rgb.at(y, x, c)) / 255.0f;
                img_rgb_norm[(y * w + x) * 3 + c] = v;
                if (v < norm_min) norm_min = v;
                if (v > norm_max) norm_max = v;
            }
        }
    }

    std::cout << "\nNormalizado (float32): faixa=[" 
              << std::fixed << std::setprecision(2) << norm_min << ", " << norm_max << "]\n";

    // Pixel (0,0) normalizado
    std::cout << "Pixel (0,0) normalizado: ["
              << img_rgb_norm[0] << ", "
              << img_rgb_norm[1] << ", "
              << img_rgb_norm[2] << "]\n";

    // ── Visualização ──────────────────────────────────────────────────────────────
    mm::show(
        std::vector<mm::Image>{img_rgb, img_rgba},
        MM_OUT,
        std::vector<std::string>{"RGB  —  M × N × 3", "RGBA  —  M × N × 4"},
        2
    );

    return 0;
}

