#include <iostream>
#include <string>
#include <vector>
#include <random>
#include <functional>
#include <algorithm>

// Simulated HTML output for the interactive simulator
class SimulatorEP0107 {
private:
    int sliderValue = 128;
    std::vector<int> pixels;
    const int size = 16;

public:
    SimulatorEP0107() {
        generate();
    }

    void generate() {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, 255);
        pixels.clear();
        for (int i = 0; i < size; i++) {
            pixels.push_back(dis(gen));
        }
    }

    std::string render() {
        std::string html = R"(
<div id="sim-ep0107-limiarizacao" style="background-color:#fbf7ee;border-radius:18px;border:1px solid #e4dcc8;overflow:hidden;margin-top:20px;font-family:'Inter',system-ui,sans-serif;box-shadow:0 1px 2px rgba(38,36,29,0.04);position:relative;">

