      <input type="range" id="sim_ep0107_sl_thresh" min="0" max="255" value=")" + std::to_string(sliderValue) + R"(" style="width:220px;cursor:pointer;">
      <span id="sim_ep0107_vl_thresh" style="font-family:monospace;font-size:18px;font-weight:700;color:#26241d;min-width:36px;text-align:right;">)" + std::to_string(sliderValue) + R"(</span>
