            html += "<div style='width:42px;height:42px;border:1px solid #e4dcc8;border-radius:6px;display:flex;align-items:center;justify-content:center;font-size:10px;font-weight:700;font-family:monospace;user-select:none;background:rgb(" + 
                    std::to_string(val) + "," + std::to_string(val) + "," + std::to_string(val) + 
