    }
    return out;
}

// Binary cross entropy with logits
float binary_cross_entropy_with_logits(const Tensor& logits, const Tensor& target) {
    float loss = 0.0f;
    for (size_t i = 0; i < logits.data.size(); ++i) {
        float l = logits.data[i];
        float t = target.data[i];
        loss -= (t * std::log(1.0f / (1.0f + std::exp(-l))) + 
                 (1 - t) * std::log(1 - 1.0f / (1.0f + std::exp(-l))));
    }
    return loss / logits.data.size();
}

