    UNetCompacta(int canais_entrada = 1, int base = 8)
        : enc1(canais_entrada, base),
          enc2(base, base * 2),
          enc3(base * 2, base * 4),
          pool(2),
          fundo(base * 4, base * 8),
          up3(base * 8, base * 4, 2, 2),
          dec3(base * 8, base * 4),
          up2(base * 4, base * 2, 2, 2),
          dec2(base * 4, base * 2),
          up1(base * 2, base, 2, 2),
          dec1(base * 2, base),
          saida(base, 1, 1) {}

    Tensor forward(const Tensor& x) {
        Tensor e1 = enc1.forward(x);
        Tensor e2 = enc2.forward(pool.forward(e1));
        Tensor e3 = enc3.forward(pool.forward(e2));
        Tensor f = fundo.forward(pool.forward(e3));

        Tensor d3 = dec3.forward(cat(up3.forward(f), e3, 1));
        Tensor d2 = dec2.forward(cat(up2.forward(d3), e2, 1));
        Tensor d1 = dec1.forward(cat(up1.forward(d2), e1, 1));
        return saida.forward(d1);
    }
};

