<script>
(function(){
  function initSim08Orb(root){
    if (!root || root.dataset.sim08OrbInit) return;
    root.dataset.sim08OrbInit = "1";

    const canvas = root.querySelector("#sim-08-orb_canvas");
    const ctx = canvas.getContext("2d");
    const W = canvas.width, H = canvas.height;

    let angleDeg = 0;
    let noiseLevel = 0;

    const numPairs = 32;
    const pairsSource = [];

    // Gerar pares pseudo-aleatórios determinísticos de teste BRIEF
    for (let i = 0; i < numPairs; i++) {
      const r1 = 5 + (i * 1.1) % 35;
      const t1 = (i * 2.39) % (2 * Math.PI);
      const r2 = 5 + (i * 1.7) % 35;
      const t2 = (i * 3.14) % (2 * Math.PI);
      pairsSource.push({
        ax: r1 * Math.cos(t1), ay: r1 * Math.sin(t1),
        bx: r2 * Math.cos(t2), by: r2 * Math.sin(t2)
      });
    }

    function getPixelIntensity(px, py, rotationRad) {
      const c = Math.cos(-rotationRad);
      const s = Math.sin(-rotationRad);
      const rx = px * c - py * s;
      const ry = px * s + py * c;

      let val = 128;
      if (rx > 0 && ry > 0) val = 200; 
      if (rx < -5 && ry > 5) val = 45; 
      if (rx * rx + ry * ry < 15 * 15) val = 220; 

      if (noiseLevel > 0) {
        val += (Math.random() - 0.5) * noiseLevel;
      }
      return Math.min(255, Math.max(0, val));
    }

    function getCentroidOrientation(rotationRad) {
      let m10 = 0, m01 = 0;
      const step = 4;
      const R = 30;
      for (let x = -R; x <= R; x += step) {
        for (let y = -R; y <= R; y += step) {
          if (x * x + y * y <= R * R) {
            const intensity = getPixelIntensity(x, y, rotationRad);
            m10 += x * intensity;
            m01 += y * intensity;
          }
        }
      }
      return Math.atan2(m01, m10);
    }

    function drawPatchBg(cx, cy, r, rotationRad) {
      const cellSize = 5;
      for (let x = -r; x < r; x += cellSize) {
        for (let y = -r; y < r; y += cellSize) {
          if (x * x + y * y <= r * r) {
            const intensity = getPixelIntensity(x, y, rotationRad);
            ctx.fillStyle = `rgb(${intensity}, ${intensity}, ${intensity})`;
            ctx.fillRect(cx + x, cy + y, cellSize, cellSize);
          }
        }
      }
      ctx.strokeStyle = "#8a8371";
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(cx, cy, r, 0, 2 * Math.PI);
      ctx.stroke();
    }

    function computeDescriptor(rotationRad, estimatedOrient) {
      const desc = [];
      for (let i = 0; i < numPairs; i++) {
        const p = pairsSource[i];
        const c = Math.cos(estimatedOrient);
        const s = Math.sin(estimatedOrient);

        const axRot = p.ax * c - p.ay * s;
        const ayRot = p.ax * s + p.ay * c;
        const bxRot = p.bx * c - p.by * s;
        const byRot = p.bx * s + p.by * c;

        const valA = getPixelIntensity(axRot, ayRot, rotationRad);
        const valB = getPixelIntensity(bxRot, byRot, rotationRad);

        desc.push(valA < valB ? 1 : 0);
      }
      return desc;
    }

    function drawBriefTestGrid(cx, cy, rotationRad, estimatedOrient, desc) {
      const c = Math.cos(estimatedOrient);
      const s = Math.sin(estimatedOrient);

      for (let i = 0; i < numPairs; i++) {
        const p = pairsSource[i];
        const axRot = cx + (p.ax * c - p.ay * s);
        const ayRot = cy + (p.ax * s + p.ay * c);
        const bxRot = cx + (p.bx * c - p.by * s);
        const byRot = cy + (p.bx * s + p.by * c);

        ctx.strokeStyle = desc[i] === 1 ? "rgba(39, 174, 96, 0.9)" : "rgba(192, 57, 43, 0.9)";
        ctx.lineWidth = 2;

        ctx.beginPath();
        ctx.moveTo(axRot, ayRot);
        ctx.lineTo(bxRot, byRot);
        ctx.stroke();

        ctx.fillStyle = "rgba(39, 174, 96, 0.8)";
        ctx.fillRect(axRot - 1.5, ayRot - 1.5, 3, 3);
        ctx.fillStyle = "rgba(192, 57, 43, 0.8)";
        ctx.fillRect(bxRot - 1.5, byRot - 1.5, 3, 3);
      }
    }

    function drawOrientationArrow(cx, cy, orient) {
      const arrowLen = 50;
      const ax = cx + arrowLen * Math.cos(orient);
      const ay = cy + arrowLen * Math.sin(orient);

      ctx.strokeStyle = "#b9770e";
      ctx.lineWidth = 2.5;
      ctx.beginPath();
      ctx.moveTo(cx, cy);
      ctx.lineTo(ax, ay);
      ctx.stroke();

      ctx.beginPath();
      ctx.arc(cx, cy, 4, 0, 2 * Math.PI);
      ctx.fillStyle = "#b9770e";
      ctx.fill();

      const angle = Math.atan2(ay - cy, ax - cx);
      ctx.beginPath();
      ctx.moveTo(ax, ay);
      ctx.lineTo(ax - 8 * Math.cos(angle - Math.PI / 6), ay - 8 * Math.sin(angle - Math.PI / 6));
      ctx.lineTo(ax - 8 * Math.cos(angle + Math.PI / 6), ay - 8 * Math.sin(angle + Math.PI / 6));
      ctx.closePath();
      ctx.fillStyle = "#b9770e";
      ctx.fill();
    }

    function render() {
      ctx.clearRect(0, 0, W, H);

      const leftCenterX = W / 4, rightCenterX = 3 * W / 4;
      const centerY = H / 2;
      const patchRadius = 80;

      // 1. Desenhar a imagem de fundo em ambas as visões
      drawPatchBg(leftCenterX, centerY, patchRadius, 0);
      drawPatchBg(rightCenterX, centerY, patchRadius, angleDeg * Math.PI / 180);

      // 2. Computar orientações locais via centroide de intensidade
      const orientOriginal = getCentroidOrientation(0);
      const angleRad = angleDeg * Math.PI / 180;
      const orientRotated = getCentroidOrientation(angleRad);

      // 3. Gerar descritores
      const descOriginal = computeDescriptor(0, orientOriginal);
      const descRotated = computeDescriptor(angleRad, orientRotated);

      // 4. Desenhar pares de amostragem
      drawBriefTestGrid(leftCenterX, centerY, 0, orientOriginal, descOriginal);
      drawBriefTestGrid(rightCenterX, centerY, angleRad, orientRotated, descRotated);

      // 5. Linhas de orientação
      drawOrientationArrow(leftCenterX, centerY, orientOriginal);
      drawOrientationArrow(rightCenterX, centerY, orientRotated);

      // 6. Distância de Hamming
      let hammingDist = 0;
      for (let i = 0; i < numPairs; i++) {
        if (descOriginal[i] !== descRotated[i]) hammingDist++;
      }

      root.querySelector("#sim-08-orb_bits").textContent = descRotated.join("");
      root.querySelector("#sim-08-orb_hammVal").textContent = hammingDist;
      root.querySelector("#sim-08-orb_angVal").textContent = angleDeg + "°";
      root.querySelector("#sim-08-orb_slVal").textContent = angleDeg;

      ctx.font = "bold 11px Inter, sans-serif";
      ctx.fillStyle = "#fafaf7";
      ctx.textAlign = "center";
      ctx.fillText("Voisinage Original (θ = 0°)", leftCenterX, centerY - patchRadius - 15);
      ctx.fillText("Voisinage Roté (aligné sur θ)", rightCenterX, centerY - patchRadius - 15);

      ctx.strokeStyle = "#8a8371";
      ctx.lineWidth = 1;
      ctx.setLineDash([4, 4]);
      ctx.beginPath();
      ctx.moveTo(W / 2, 10);
      ctx.lineTo(W / 2, H - 10);
      ctx.stroke();
      ctx.setLineDash([]);
    }

    const slider = root.querySelector("#sim-08-orb_slider");
    slider.addEventListener("input", function(ev){
      angleDeg = parseInt(ev.target.value, 10);
      render();
    });

    root.querySelector("#sim-08-orb_btnRot").addEventListener("click", function(){
      angleDeg = (angleDeg + 15) % 180;
      if (angleDeg > 180) angleDeg -= 360;
      slider.value = angleDeg;
      render();
    });

    root.querySelector("#sim-08-orb_btnReset").addEventListener("click", function(){
      angleDeg = 0;
      noiseLevel = 0;
      slider.value = 0;
      const btnNoise = root.querySelector("#sim-08-orb_btnNoise");
      btnNoise.classList.remove("sim-08-orb_active");
      btnNoise.textContent = "⚡ Ajouter du Bruit";
      render();
    });

    const noiseStep = 15;
    const maxNoise = 150;
    root.querySelector("#sim-08-orb_btnNoise").addEventListener("click", function(){
      noiseLevel = Math.min(noiseLevel + noiseStep, maxNoise);
      this.textContent = "⚡ Bruit (" + noiseLevel + ")";
      this.classList.toggle("sim-08-orb_active", noiseLevel > 0);
      render();
    });

    render();
  }

  function tryInitSim08Orb(){
    var root = document.getElementById("sim-08-orb");
    if (root) initSim08Orb(root); else setTimeout(tryInitSim08Orb, 200);
  }
  tryInitSim08Orb();
})();
</script>
</div>
""")

