#include "morph.hpp"
#include <vector>
#include <algorithm>
#include <numeric>
#include <cmath>
#include <iostream>
#include <string>

// #| label: fig-01-sim-ep0104-estatisticas
// #| fig-cap: "Simulador EP01_04: Estatísticas de Pixels em Matriz Discreta 5x5"
// #| echo: false
// #| output: true

// Simulação interativa não é diretamente traduzível para C++ estático.
// Esta tradução representa a lógica de cálculo estatístico que o simulador executaria.
// A visualização HTML interativa não tem equivalente direto em C++.

int main() {
    // Simula a matriz 5x5 de pixels
    int width = 5, height = 5;
    std::vector<int> pixels(25, 0);

    // Inicialização aleatória (simula o estado inicial do simulador)
    srand(static_cast<unsigned>(time(nullptr)));
    for (int i = 0; i < 25; ++i) {
        pixels[i] = rand() % 256;
    }

    // Calcula estatísticas
    auto updateStats = [&]() {
        int maxVal = *std::max_element(pixels.begin(), pixels.end());
        int minVal = *std::min_element(pixels.begin(), pixels.end());
        double sum = std::accumulate(pixels.begin(), pixels.end(), 0);
        double avgVal = sum / pixels.size();

        std::cout << "=== Estatísticas da Matriz 5x5 ===" << std::endl;
        std::cout << "Valor Máximo: " << maxVal << std::endl;
        std::cout << "Valor Mínimo: " << minVal << std::endl;
        std::cout << "Média Global (µ): " << avgVal << std::endl;
        std::cout << std::endl;

        // Exibe a matriz
        std::cout << "Matriz:" << std::endl;
        for (int y = 0; y < height; ++y) {
            for (int x = 0; x < width; ++x) {
                std::cout << pixels[y * width + x] << "\t";
            }
            std::cout << std::endl;
        }
    };

    // Apresenta o estado inicial
    updateStats();

    // Simula a ação "Aleatório" (botão 🎲)
    std::cout << "\n--- Ação: Aleatório ---" << std::endl;
    for (int i = 0; i < 25; ++i) {
        pixels[i] = rand() % 256;
    }
    updateStats();

    // Simula a ação "Zerar" (botão ⬛)
    std::cout << "\n--- Ação: Zerar (Min = 0) ---" << std::endl;
    std::fill(pixels.begin(), pixels.end(), 0);
    updateStats();

    // Simula a ação "Máximo" (botão ⬜)
    std::cout << "\n--- Ação: Máximo (Max = 255) ---" << std::endl;
    std::fill(pixels.begin(), pixels.end(), 255);
    updateStats();

    // Simula cliques em pixels (incremento de +51)
    std::cout << "\n--- Simulação de cliques (+51 em 3 pixels) ---" << std::endl;
    pixels[0] = (pixels[0] + 51) % 256;
    pixels[12] = (pixels[12] + 51) % 256;
    pixels[24] = (pixels[24] + 51) % 256;
    updateStats();

    return 0;
}

