        scenBtns.forEach(function(b) {
          b.style.background = '#f1ead7';
          b.style.color = '#5e5a4a';
          b.style.borderColor = '#e4dcc8';
        });
        update();
      });
    });

    scenBtns.forEach(function(btn) {
      btn.addEventListener('click', function() { setScenario(this); });
    });

    setScenario(btnScen1);
