// Compile: g++ -std=c++17 -o programa programa.cpp -I./morph -L./morph -lmorph

#include "morph.hpp"
#include <iostream>
#include <vector>
#include <string>
#include <cmath>
#include <algorithm>
#include <complex>

// Função para calcular FFT2 simplificada (apenas para demonstração didática)
// Nota: Esta é uma implementação simplificada da FFT para fins educacionais
mm::Image fft2(const mm::Image& img) {
    int h = img.h, w = img.w;
    mm::Image result(h, w);

    // Implementação FFT 2D simplificada (DFT direta)
    for (int u = 0; u < h; u++) {
        for (int v = 0; v < w; v++) {
            std::complex<double> sum(0.0, 0.0);
            for (int x = 0; x < h; x++) {
                for (int y = 0; y < w; y++) {
                    double angle = -2.0 * M_PI * (static_cast<double>(u)*x/h + static_cast<double>(v)*y/w);
                    std::complex<double> exp_val(std::cos(angle), std::sin(angle));
                    sum += std::complex<double>(static_cast<double>(img.at(x, y)), 0.0) * exp_val;
                }
            }
            double mag = std::abs(sum);
            result.at(u, v) = static_cast<unsigned char>(std::min(255.0, mag));
        }
    }
    return result;
}

// Função para fftshift
mm::Image fftshift(const mm::Image& img) {
    int h = img.h, w = img.w;
    mm::Image result(h, w);
    int h2 = h / 2, w2 = w / 2;

    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            int i_shift = (i + h2) % h;
            int j_shift = (j + w2) % w;
            result.at(i, j) = img.at(i_shift, j_shift);
        }
    }
    return result;
}

// Função log1p
mm::Image log1p_img(const mm::Image& img) {
    int h = img.h, w = img.w;
    mm::Image result(h, w);

    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            double val = static_cast<double>(img.at(i, j));
            double log_val = std::log1p(val);
            result.at(i, j) = static_cast<unsigned char>(std::min(255.0, log_val * 10.0));
        }
    }
    return result;
}

int main() {
    // Criação das imagens dos sinais
    mm::Image img_sinal1(128, 128);
    mm::Image img_sinal2(128, 128);

    // Sinal 1: barras verticais e horizontais
    for (int i = 0; i < 128; i++) {
        for (int j = 20; j < 25; j++) {
            img_sinal1.at(i, j) = 255;
        }
    }
    for (int i = 100; i < 105; i++) {
        for (int j = 0; j < 128; j++) {
            img_sinal1.at(i, j) = 255;
        }
    }

    // Sinal 2: barras verticais e horizontais (deslocadas)
    for (int i = 0; i < 128; i++) {
        for (int j = 90; j < 95; j++) {
            img_sinal2.at(i, j) = 255;
        }
    }
    for (int i = 30; i < 35; i++) {
        for (int j = 0; j < 128; j++) {
            img_sinal2.at(i, j) = 255;
        }
    }

    // Cálculo dos espectros (FFT + fftshift + log1p(abs))
    mm::Image fft1 = fft2(img_sinal1);
    mm::Image fft_shifted1 = fftshift(fft1);
    mm::Image mag1 = log1p_img(fft_shifted1);

    mm::Image fft2_img = fft2(img_sinal2);
    mm::Image fft_shifted2 = fftshift(fft2_img);
    mm::Image mag2 = log1p_img(fft_shifted2);

    // Exibição dos resultados
    mm::show(std::vector<mm::Image>{img_sinal1, mag1, img_sinal2, mag2},
             MM_OUT,
             std::vector<std::string>{"Sinal A", "Espectro A", "Sinal B (Deslocado)", "Espectro B"},
             4);

    return 0;
}

