// Compile: g++ -std=c++17 -I. -o cnn cnn.cpp -lmorph

#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <random>

// Classes pour la couche convolutive
class Conv2d {
public:
    int in_channels, out_channels, kernel_size, padding;
    std::vector<std::vector<std::vector<std::vector<double>>>> weights;
    std::vector<double> bias;

    Conv2d(int in_ch, int out_ch, int k_size, int pad) 
        : in_channels(in_ch), out_channels(out_ch), kernel_size(k_size), padding(pad) {
        // Initialisation aléatoire des poids (simplifiée)
        std::random_device rd;
        std::mt19937 gen(rd());
        std::normal_distribution<double> dist(0.0, 0.1);

        weights.resize(out_channels);
        for (int oc = 0; oc < out_channels; oc++) {
            weights[oc].resize(in_channels);
            for (int ic = 0; ic < in_channels; ic++) {
                weights[oc][ic].resize(kernel_size);
                for (int i = 0; i < kernel_size; i++) {
                    weights[oc][ic][i].resize(kernel_size);
                    for (int j = 0; j < kernel_size; j++) {
                        weights[oc][ic][i][j] = dist(gen);
                    }
                }
            }
            bias.push_back(dist(gen));
        }
    }

    std::vector<std::vector<std::vector<double>>> operator()(
        const std::vector<std::vector<std::vector<double>>>& input) {

        int h = input.size();
        int w = input[0].size();
        int out_h = h - kernel_size + 1 + 2 * padding;
        int out_w = w - kernel_size + 1 + 2 * padding;

        std::vector<std::vector<std::vector<double>>> output(
            out_channels, std::vector<std::vector<double>>(
                out_h, std::vector<double>(out_w, 0.0)));

        for (int oc = 0; oc < out_channels; oc++) {
            for (int i = 0; i < out_h; i++) {
                for (int j = 0; j < out_w; j++) {
                    double sum = bias[oc];
                    for (int ic = 0; ic < in_channels; ic++) {
                        for (int ki = 0; ki < kernel_size; ki++) {
                            for (int kj = 0; kj < kernel_size; kj++) {
                                int pi = i + ki - padding;
                                int pj = j + kj - padding;
                                if (pi >= 0 && pi < h && pj >= 0 && pj < w) {
                                    sum += weights[oc][ic][ki][kj] * input[ic][pi][pj];
                                }
                            }
                        }
                    }
                    output[oc][i][j] = sum;
                }
            }
        }
        return output;
    }
};

// Classe ReLU
class ReLU {
public:
    std::vector<std::vector<std::vector<double>>> operator()(
        const std::vector<std::vector<std::vector<double>>>& input) {
        auto output = input;
        for (auto& channel : output) {
            for (auto& row : channel) {
                for (auto& val : row) {
                    val = std::max(0.0, val);
                }
            }
        }
        return output;
    }
};

// Classe MaxPool2d
class MaxPool2d {
public:
    int kernel_size, stride;

    MaxPool2d(int k, int s) : kernel_size(k), stride(s) {}

    std::vector<std::vector<std::vector<double>>> operator()(
        const std::vector<std::vector<std::vector<double>>>& input) {

        int channels = input.size();
        int h = input[0].size();
        int w = input[0][0].size();
        int out_h = (h - kernel_size) / stride + 1;
        int out_w = (w - kernel_size) / stride + 1;

        std::vector<std::vector<std::vector<double>>> output(
            channels, std::vector<std::vector<double>>(
                out_h, std::vector<double>(out_w, 0.0)));

        for (int c = 0; c < channels; c++) {
            for (int i = 0; i < out_h; i++) {
                for (int j = 0; j < out_w; j++) {
                    double max_val = -1e9;
                    for (int ki = 0; ki < kernel_size; ki++) {
                        for (int kj = 0; kj < kernel_size; kj++) {
                            int pi = i * stride + ki;
                            int pj = j * stride + kj;
                            max_val = std::max(max_val, input[c][pi][pj]);
                        }
                    }
                    output[c][i][j] = max_val;
                }
            }
        }
        return output;
    }
};

// Classe Linear (couche dense)
class Linear {
public:
    int in_features, out_features;
    std::vector<std::vector<double>> weights;
    std::vector<double> bias;

    Linear(int in_f, int out_f) : in_features(in_f), out_features(out_f) {
        // Initialisation aléatoire des poids
        std::random_device rd;
        std::mt19937 gen(rd());
        std::normal_distribution<double> dist(0.0, 0.1);

        weights.resize(out_features);
        for (int i = 0; i < out_features; i++) {
            weights[i].resize(in_features);
            for (int j = 0; j < in_features; j++) {
                weights[i][j] = dist(gen);
            }
        }

        for (int i = 0; i < out_features; i++) {
            bias.push_back(dist(gen));
        }
    }

    std::vector<double> operator()(const std::vector<double>& input) {
        std::vector<double> output(out_features, 0.0);
        for (int i = 0; i < out_features; i++) {
            output[i] = bias[i];
            for (int j = 0; j < in_features; j++) {
                output[i] += weights[i][j] * input[j];
            }
        }
        return output;
    }
};

// Flatten : conversion 3D -> 1D
std::vector<double> flatten(const std::vector<std::vector<std::vector<double>>>& input) {
    std::vector<double> output;
    for (const auto& channel : input) {
        for (const auto& row : channel) {
            for (double val : row) {
                output.push_back(val);
            }
        }
    }
    return output;
}

// Définition de l'Architecture Convolutionnelle
// Architecture convolutionnelle compacte :
// 2 couches convolutionnelles avec ReLU et Max-Pooling + 2 couches denses.
class CNNDigitos {
public:
    Conv2d conv1;
    Conv2d conv2;
    ReLU relu;
    MaxPool2d pool;
    Linear fc1;
    Linear fc2;

    // Conv1 : 1 canal d'entrée, 8 filtres 3x3 avec padding 1 (sortie : 8x8)
    // Conv2 : 8 canaux d'entrée, 16 filtres 3x3 avec padding 1 (sortie : 4x4)
    // Max-Pooling 2x2 avec pas (stride) 2
    // Couches entièrement connectées (FC) : 64 -> 32 -> n_classes
    explicit CNNDigitos(int n_classes = 10)
        : conv1(1, 8, 3, 1), conv2(8, 16, 3, 1), pool(2, 2), 
          fc1(16 * 2 * 2, 32), fc2(32, n_classes) {}

    // Propagation avant (forward)
    std::vector<double> forward(const std::vector<std::vector<std::vector<double>>>& x) {
        // Premier bloc : Conv (8x8) -> ReLU -> Pool (4x4)
        auto out = conv1(x);
        out = relu(out);
        out = pool(out);

        // Deuxième bloc : Conv (4x4) -> ReLU -> Pool (2x2)
        out = conv2(out);
        out = relu(out);
        out = pool(out);

        // Aplatissement (Flatten) : reconfigure la matrice 3D (16, 2, 2) en vecteur 1D (64)
        auto flat = flatten(out);

        // Couche dense intermédiaire avec ReLU
        auto fc1_out = fc1(flat);
        for (auto& val : fc1_out) {
            val = std::max(0.0, val); // ReLU
        }

        // Couche finale de classification (logits)
        return fc2(fc1_out);
    }
};

int main() {
    // Test du modèle avec une entrée d'exemple
    CNNDigitos model(10);

    // Entrée simulée : image 8x8 avec 1 canal
    std::vector<std::vector<std::vector<double>>> input(
        1, std::vector<std::vector<double>>(
            8, std::vector<double>(8, 0.0)));

    // Remplir avec des valeurs de test
    for (int i = 0; i < 8; i++) {
        for (int j = 0; j < 8; j++) {
            input[0][i][j] = (i + j) % 255 / 255.0;
        }
    }

    std::cout << "Test du modèle CNN" << std::endl;
    auto output = model.forward(input);

    std::cout << "Sortie (logits) : ";
    for (double val : output) {
        std::cout << val << " ";
    }
    std::cout << std::endl;

    return 0;
}

